/****************************************************************************
 * 安聆 VelaGuard - 公共类型与结构化事件协议 (PRD-01/03/05)
 *
 * 本文件只依赖 C 标准库与 POSIX，可同时在 openvela/NuttX 与主机侧单元测试
 * 环境中编译。
 ****************************************************************************/

#ifndef __VELAGUARD_VG_TYPES_H
#define __VELAGUARD_VG_TYPES_H

#include <stdbool.h>
#include <stdint.h>
#include <stddef.h>

#ifdef __cplusplus
extern "C"
{
#endif

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define VG_EVENT_ID_LEN     24
#define VG_DEVICE_ID_LEN    32
#define VG_PHRASE_LEN       32
#define VG_LABEL_LEN        24
#define VG_SUMMARY_LEN      128
#define VG_TIMESTR_LEN      32

/* 本地事件日志容量：PRD-05 规定最多 100 条，写满环形覆盖 */

#define VG_EVENT_LOG_CAPACITY 100

/****************************************************************************
 * Public Types
 ****************************************************************************/

/* 五类安全声景 eventType (PRD-05) */

typedef enum
{
  VG_EVT_ALARM_BEEP = 0,      /* 烟雾/燃气报警蜂鸣 */
  VG_EVT_DISTRESS_VOICE,      /* 呻吟/痛苦叫声/哭喊/连续呼救 */
  VG_EVT_WATER_FLOW,          /* 持续水流/疑似漏水 */
  VG_EVT_NAME_CALL_HELP,      /* 姓名/亲属称呼/方言求救词 */
  VG_EVT_IMPACT,              /* 玻璃破碎/重物撞击 */
  VG_EVT_TYPE_MAX
} vg_event_type_t;

/* 告警三级 (PRD-03) */

typedef enum
{
  VG_LEVEL_NONE = -1,
  VG_LEVEL_NOTICE = 0,
  VG_LEVEL_WARNING,
  VG_LEVEL_EMERGENCY
} vg_level_t;

/* 本地处理状态 (PRD-05) */

typedef enum
{
  VG_STATUS_PENDING = 0,
  VG_STATUS_HANDLED,
  VG_STATUS_FALSE_ALARM,
  VG_STATUS_SNOOZED,
  VG_STATUS_NO_RESPONSE
} vg_local_status_t;

/* 上传原因 (PRD-05) */

typedef enum
{
  VG_UPLOAD_MANUAL_TEST = 0,
  VG_UPLOAD_ESCALATED,
  VG_UPLOAD_SYNC
} vg_upload_reason_t;

/* 状态机内部状态 (PRD-03 状态集合) */

typedef enum
{
  VG_STATE_IDLE = 0,          /* 正常监测 */
  VG_STATE_SUSPECT,           /* 可疑：已有命中但未达提醒阈值 */
  VG_STATE_NOTICE,            /* 提醒 */
  VG_STATE_WARNING,           /* 警告：倒计时等待确认 */
  VG_STATE_EMERGENCY,         /* 紧急 */
  VG_STATE_SNOOZED,           /* 稍后提醒 */
  VG_STATE_CLOSED             /* 已处理/误报，事件结束 */
} vg_state_t;

/* 识别层声音类别 (PRD-01 环境声景通道) */

typedef enum
{
  VG_SOUND_OTHER = 0,         /* 背景噪声/普通说话（负样本） */
  VG_SOUND_ALARM_BEEP,
  VG_SOUND_WATER_FLOW,
  VG_SOUND_IMPACT,
  VG_SOUND_CLASS_MAX
} vg_sound_class_t;

/* 识别层人声异常类别 (PRD-01 人声通道 + PRD-02 模板通道) */

typedef enum
{
  VG_VOICE_NONE = 0,
  VG_VOICE_MOAN,              /* 呻吟 */
  VG_VOICE_SCREAM,            /* 痛苦叫声/哭喊 */
  VG_VOICE_SHOUT_HELP,        /* 连续呼救 */
  VG_VOICE_NAME_CALL,         /* 呼喊姓名/亲属称呼 */
  VG_VOICE_HELP_PHRASE,       /* 明确求救短语（含方言） */
  VG_VOICE_KIND_MAX
} vg_voice_kind_t;

/* PRD-01 输出接口：环境声景观测 */

typedef struct
{
  uint64_t         ts_ms;        /* 单调时钟毫秒 */
  vg_sound_class_t cls;
  float            confidence;   /* 0.0 ~ 1.0 */
  uint16_t         window_ms;    /* 观测窗口长度 */
} vg_sound_obs_t;

/* PRD-01 输出接口：人声异常观测
 *
 * 明确不含对话文本与原始音频，只有类别、模板标签与统计量。
 */

typedef struct
{
  uint64_t        ts_ms;
  vg_voice_kind_t kind;
  char            matched_phrase[VG_PHRASE_LEN];  /* 命中的本地模板短语 */
  char            person_label[VG_LABEL_LEN];     /* 预设标签，如"家庭成员 A" */
  float           confidence;
  float           urgency;       /* 急促程度 0.0(平静) ~ 1.0(急促) */
  uint16_t        repeat_count;  /* 观测窗口内重复次数 */
} vg_distress_obs_t;

/* PRD-05 结构化事件协议 */

typedef struct
{
  char               event_id[VG_EVENT_ID_LEN];
  char               device_id[VG_DEVICE_ID_LEN];
  vg_event_type_t    type;
  vg_level_t         level;
  float              confidence;
  int64_t            started_at;      /* Unix 秒（墙钟） */
  uint32_t           duration_sec;
  vg_local_status_t  local_status;
  vg_upload_reason_t upload_reason;
  bool               time_reliable;   /* 时间是否可信（NTP 已同步） */
  bool               night;           /* 事件发生时是否判定为夜间 */

  /* 人声事件可选附加字段 */

  char               matched_phrase[VG_PHRASE_LEN];
  char               person_label[VG_LABEL_LEN];
  float              urgency;
  uint16_t           repeat_count;

  char               summary[VG_SUMMARY_LEN];
} vg_safety_event_t;

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/* 枚举 <-> 协议字符串 */

const char *vg_event_type_str(vg_event_type_t type);
const char *vg_level_str(vg_level_t level);
const char *vg_status_str(vg_local_status_t status);
const char *vg_upload_reason_str(vg_upload_reason_t reason);
const char *vg_state_str(vg_state_t state);
const char *vg_sound_class_str(vg_sound_class_t cls);
const char *vg_voice_kind_str(vg_voice_kind_t kind);

int vg_event_type_parse(const char *s, vg_event_type_t *out);
int vg_level_parse(const char *s, vg_level_t *out);
int vg_status_parse(const char *s, vg_local_status_t *out);
int vg_voice_kind_parse(const char *s, vg_voice_kind_t *out);

/* 中文显示名（LCD / 通知文案用） */

const char *vg_event_type_cn(vg_event_type_t type);
const char *vg_level_cn(vg_level_t level);
const char *vg_status_cn(vg_local_status_t status);

/* 事件优先级：数值越大越优先 (PRD-03 并发仲裁) */

int vg_event_priority(const vg_safety_event_t *evt);

/* 比较两个事件的展示优先级，返回 >0 表示 a 更优先 */

int vg_event_cmp_priority(const vg_safety_event_t *a,
                          const vg_safety_event_t *b);

/* 将 Unix 秒格式化为 ISO8601 (+08:00)，供协议字段使用 */

void vg_format_time(int64_t unix_sec, char *buf, size_t len);

/* 事件 -> JSON（结构化摘要，禁止包含原始音频/对话文本）
 * 返回写入的字节数（不含结尾 '\0'），失败返回负值。
 */

int vg_event_to_json(const vg_safety_event_t *evt, char *buf, size_t len);

/* JSON -> 事件（供控制台回填与单元测试用，容错的扁平解析） */

int vg_event_from_json(const char *json, vg_safety_event_t *evt);

/* 事件字段合法性校验，返回 0 合法，负值为第一个非法字段编号 */

int vg_event_validate(const vg_safety_event_t *evt);

#ifdef __cplusplus
}
#endif

#endif /* __VELAGUARD_VG_TYPES_H */

/****************************************************************************
 * 安聆 VelaGuard - 极简 JSON 读写辅助
 *
 * 端侧只需要处理扁平的结构化事件摘要与配置文件，因此不引入完整 JSON 库，
 * 避免闪存增量与额外依赖（PRD-07 资源预算）。
 ****************************************************************************/

#ifndef __VELAGUARD_VG_JSON_H
#define __VELAGUARD_VG_JSON_H

#include <stdbool.h>
#include <stddef.h>

#ifdef __cplusplus
extern "C"
{
#endif

/* 从扁平 JSON 文本中取出 "key" 对应的字符串值（自动反转义 \" \\ \n \t \uXXXX）。
 * 找到返回 0，未找到返回 -1。
 */

int vg_json_get_str(const char *json, const char *key,
                    char *out, size_t len);

/* 取数值。找到返回 0。 */

int vg_json_get_double(const char *json, const char *key, double *out);
int vg_json_get_int(const char *json, const char *key, int *out);
int vg_json_get_i64(const char *json, const char *key, long long *out);
int vg_json_get_bool(const char *json, const char *key, bool *out);

/* 向缓冲区追加一个转义后的 JSON 字符串（含引号）。
 * pos 为当前写入偏移，返回新的偏移；缓冲区不足时截断但保持合法结尾。
 */

size_t vg_json_put_escaped(char *buf, size_t len, size_t pos, const char *s);

#ifdef __cplusplus
}
#endif

#endif /* __VELAGUARD_VG_JSON_H */

/****************************************************************************
 * 安聆 VelaGuard - 极简 JSON 读写辅助实现
 ****************************************************************************/

#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "velaguard/vg_json.h"

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* 在 json 中定位 "key" 之后的值起始位置，跳过空白与冒号。
 * 只在对象键位置匹配（即引号包裹且紧跟冒号），避免命中普通字符串内容。
 */

static const char *vg_json_find_value(const char *json, const char *key)
{
  size_t keylen = strlen(key);
  const char *p = json;

  if (json == NULL || key == NULL)
    {
      return NULL;
    }

  while ((p = strchr(p, '"')) != NULL)
    {
      const char *k = p + 1;

      if (strncmp(k, key, keylen) == 0 && k[keylen] == '"')
        {
          const char *q = k + keylen + 1;

          while (*q == ' ' || *q == '\t' || *q == '\n' || *q == '\r')
            {
              q++;
            }

          if (*q == ':')
            {
              q++;
              while (*q == ' ' || *q == '\t' || *q == '\n' || *q == '\r')
                {
                  q++;
                }

              return q;
            }
        }

      p = k;
    }

  return NULL;
}

/* 把 UTF-16 码点写成 UTF-8，返回写入字节数 */

static size_t vg_utf8_encode(unsigned int cp, char *out, size_t room)
{
  if (cp < 0x80 && room >= 1)
    {
      out[0] = (char)cp;
      return 1;
    }

  if (cp < 0x800 && room >= 2)
    {
      out[0] = (char)(0xc0 | (cp >> 6));
      out[1] = (char)(0x80 | (cp & 0x3f));
      return 2;
    }

  if (room >= 3)
    {
      out[0] = (char)(0xe0 | (cp >> 12));
      out[1] = (char)(0x80 | ((cp >> 6) & 0x3f));
      out[2] = (char)(0x80 | (cp & 0x3f));
      return 3;
    }

  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int vg_json_get_str(const char *json, const char *key, char *out, size_t len)
{
  const char *v = vg_json_find_value(json, key);
  size_t o = 0;

  if (v == NULL || *v != '"' || out == NULL || len == 0)
    {
      return -1;
    }

  v++;
  while (*v != '\0' && *v != '"' && o + 1 < len)
    {
      if (*v == '\\')
        {
          v++;
          switch (*v)
            {
              case 'n': out[o++] = '\n'; v++; break;
              case 't': out[o++] = '\t'; v++; break;
              case 'r': out[o++] = '\r'; v++; break;
              case 'b': out[o++] = '\b'; v++; break;
              case 'f': out[o++] = '\f'; v++; break;
              case 'u':
                {
                  char hex[5];
                  unsigned int cp;
                  size_t n;

                  if (strlen(v + 1) < 4)
                    {
                      v += strlen(v);
                      break;
                    }

                  memcpy(hex, v + 1, 4);
                  hex[4] = '\0';
                  cp = (unsigned int)strtoul(hex, NULL, 16);
                  n = vg_utf8_encode(cp, out + o, len - 1 - o);
                  o += n;
                  v += 5;
                }
                break;
              case '\0':
                break;
              default:
                out[o++] = *v++;
                break;
            }
        }
      else
        {
          out[o++] = *v++;
        }
    }

  out[o] = '\0';
  return 0;
}

int vg_json_get_double(const char *json, const char *key, double *out)
{
  const char *v = vg_json_find_value(json, key);

  if (v == NULL || out == NULL)
    {
      return -1;
    }

  if (*v != '-' && *v != '+' && !isdigit((unsigned char)*v))
    {
      return -1;
    }

  *out = strtod(v, NULL);
  return 0;
}

int vg_json_get_int(const char *json, const char *key, int *out)
{
  double d;

  if (vg_json_get_double(json, key, &d) < 0)
    {
      return -1;
    }

  *out = (int)d;
  return 0;
}

int vg_json_get_i64(const char *json, const char *key, long long *out)
{
  const char *v = vg_json_find_value(json, key);

  if (v == NULL || out == NULL)
    {
      return -1;
    }

  if (*v != '-' && *v != '+' && !isdigit((unsigned char)*v))
    {
      return -1;
    }

  *out = strtoll(v, NULL, 10);
  return 0;
}

int vg_json_get_bool(const char *json, const char *key, bool *out)
{
  const char *v = vg_json_find_value(json, key);

  if (v == NULL || out == NULL)
    {
      return -1;
    }

  if (strncmp(v, "true", 4) == 0)
    {
      *out = true;
      return 0;
    }

  if (strncmp(v, "false", 5) == 0)
    {
      *out = false;
      return 0;
    }

  return -1;
}

size_t vg_json_put_escaped(char *buf, size_t len, size_t pos, const char *s)
{
  if (buf == NULL || pos + 1 >= len)
    {
      return pos;
    }

  buf[pos++] = '"';

  for (; s != NULL && *s != '\0'; s++)
    {
      unsigned char c = (unsigned char)*s;
      const char *esc = NULL;

      switch (c)
        {
          case '"':  esc = "\\\""; break;
          case '\\': esc = "\\\\"; break;
          case '\n': esc = "\\n";  break;
          case '\r': esc = "\\r";  break;
          case '\t': esc = "\\t";  break;
          default:   break;
        }

      if (esc != NULL)
        {
          if (pos + 2 >= len)
            {
              break;
            }

          buf[pos++] = esc[0];
          buf[pos++] = esc[1];
        }
      else if (c < 0x20)
        {
          if (pos + 6 >= len)
            {
              break;
            }

          snprintf(buf + pos, len - pos, "\\u%04x", c);
          pos += 6;
        }
      else
        {
          if (pos + 1 >= len)
            {
              break;
            }

          buf[pos++] = (char)c;
        }
    }

  if (pos + 1 < len)
    {
      buf[pos++] = '"';
    }

  buf[pos] = '\0';
  return pos;
}

/****************************************************************************
 * 安聆 VelaGuard - 公共类型与结构化事件协议实现 (PRD-05)
 ****************************************************************************/

#include <inttypes.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#include "velaguard/vg_types.h"
#include "velaguard/vg_json.h"

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const char * const g_event_type_str[VG_EVT_TYPE_MAX] =
{
  "alarm_beep", "distress_voice", "water_flow", "name_call_help", "impact"
};

static const char * const g_event_type_cn[VG_EVT_TYPE_MAX] =
{
  "烟雾/燃气报警", "呻吟或呼救", "持续水流", "呼喊姓名/求救词", "破碎或撞击"
};

static const char * const g_level_str[] =
{
  "notice", "warning", "emergency"
};

static const char * const g_level_cn[] =
{
  "提醒", "警告", "紧急"
};

static const char * const g_status_str[] =
{
  "pending", "handled", "false_alarm", "snoozed", "no_response"
};

static const char * const g_status_cn[] =
{
  "待处理", "已处理", "误报", "稍后提醒", "无人响应"
};

static const char * const g_upload_reason_str[] =
{
  "manual_test", "escalated", "sync"
};

static const char * const g_state_str[] =
{
  "idle", "suspect", "notice", "warning", "emergency", "snoozed", "closed"
};

static const char * const g_sound_class_str[VG_SOUND_CLASS_MAX] =
{
  "other", "alarm_beep", "water_flow", "impact"
};

static const char * const g_voice_kind_str[VG_VOICE_KIND_MAX] =
{
  "none", "moan", "scream", "shout_help", "name_call", "help_phrase"
};

/* PRD-03 并发仲裁：同级别按类别优先级
 * distress_voice >= name_call_help > alarm_beep > impact > water_flow
 */

static const int g_type_priority[VG_EVT_TYPE_MAX] =
{
  [VG_EVT_DISTRESS_VOICE]  = 5,
  [VG_EVT_NAME_CALL_HELP]  = 4,
  [VG_EVT_ALARM_BEEP]      = 3,
  [VG_EVT_IMPACT]          = 2,
  [VG_EVT_WATER_FLOW]      = 1,
};

/****************************************************************************
 * Public Functions
 ****************************************************************************/

const char *vg_event_type_str(vg_event_type_t type)
{
  if (type < 0 || type >= VG_EVT_TYPE_MAX)
    {
      return "unknown";
    }

  return g_event_type_str[type];
}

const char *vg_event_type_cn(vg_event_type_t type)
{
  if (type < 0 || type >= VG_EVT_TYPE_MAX)
    {
      return "未知事件";
    }

  return g_event_type_cn[type];
}

const char *vg_level_str(vg_level_t level)
{
  if (level < VG_LEVEL_NOTICE || level > VG_LEVEL_EMERGENCY)
    {
      return "none";
    }

  return g_level_str[level];
}

const char *vg_level_cn(vg_level_t level)
{
  if (level < VG_LEVEL_NOTICE || level > VG_LEVEL_EMERGENCY)
    {
      return "无";
    }

  return g_level_cn[level];
}

const char *vg_status_str(vg_local_status_t status)
{
  if (status < 0 || status > VG_STATUS_NO_RESPONSE)
    {
      return "pending";
    }

  return g_status_str[status];
}

const char *vg_status_cn(vg_local_status_t status)
{
  if (status < 0 || status > VG_STATUS_NO_RESPONSE)
    {
      return "待处理";
    }

  return g_status_cn[status];
}

const char *vg_upload_reason_str(vg_upload_reason_t reason)
{
  if (reason < 0 || reason > VG_UPLOAD_SYNC)
    {
      return "sync";
    }

  return g_upload_reason_str[reason];
}

const char *vg_state_str(vg_state_t state)
{
  if (state < 0 || state > VG_STATE_CLOSED)
    {
      return "idle";
    }

  return g_state_str[state];
}

const char *vg_sound_class_str(vg_sound_class_t cls)
{
  if (cls < 0 || cls >= VG_SOUND_CLASS_MAX)
    {
      return "other";
    }

  return g_sound_class_str[cls];
}

const char *vg_voice_kind_str(vg_voice_kind_t kind)
{
  if (kind < 0 || kind >= VG_VOICE_KIND_MAX)
    {
      return "none";
    }

  return g_voice_kind_str[kind];
}

int vg_event_type_parse(const char *s, vg_event_type_t *out)
{
  int i;

  if (s == NULL || out == NULL)
    {
      return -1;
    }

  for (i = 0; i < VG_EVT_TYPE_MAX; i++)
    {
      if (strcmp(s, g_event_type_str[i]) == 0)
        {
          *out = (vg_event_type_t)i;
          return 0;
        }
    }

  return -1;
}

int vg_level_parse(const char *s, vg_level_t *out)
{
  int i;

  if (s == NULL || out == NULL)
    {
      return -1;
    }

  for (i = 0; i <= VG_LEVEL_EMERGENCY; i++)
    {
      if (strcmp(s, g_level_str[i]) == 0)
        {
          *out = (vg_level_t)i;
          return 0;
        }
    }

  return -1;
}

int vg_status_parse(const char *s, vg_local_status_t *out)
{
  int i;

  if (s == NULL || out == NULL)
    {
      return -1;
    }

  for (i = 0; i <= VG_STATUS_NO_RESPONSE; i++)
    {
      if (strcmp(s, g_status_str[i]) == 0)
        {
          *out = (vg_local_status_t)i;
          return 0;
        }
    }

  return -1;
}

int vg_voice_kind_parse(const char *s, vg_voice_kind_t *out)
{
  int i;

  if (s == NULL || out == NULL)
    {
      return -1;
    }

  for (i = 0; i < VG_VOICE_KIND_MAX; i++)
    {
      if (strcmp(s, g_voice_kind_str[i]) == 0)
        {
          *out = (vg_voice_kind_t)i;
          return 0;
        }
    }

  return -1;
}

int vg_event_priority(const vg_safety_event_t *evt)
{
  if (evt == NULL)
    {
      return -1;
    }

  /* 等级权重压倒类别权重 */

  return (int)evt->level * 100 + g_type_priority[evt->type];
}

int vg_event_cmp_priority(const vg_safety_event_t *a,
                          const vg_safety_event_t *b)
{
  int pa = vg_event_priority(a);
  int pb = vg_event_priority(b);

  if (pa != pb)
    {
      return pa - pb;
    }

  /* 同优先级时先发生的事件先展示 */

  if (a->started_at != b->started_at)
    {
      return a->started_at < b->started_at ? 1 : -1;
    }

  return 0;
}

void vg_format_time(int64_t unix_sec, char *buf, size_t len)
{
  /* 固定使用 +08:00 展示，避免依赖板端 tzdata */

  time_t t = (time_t)(unix_sec + 8 * 3600);
  struct tm tm_buf;

  if (buf == NULL || len == 0)
    {
      return;
    }

  if (gmtime_r(&t, &tm_buf) == NULL)
    {
      snprintf(buf, len, "1970-01-01T08:00:00+08:00");
      return;
    }

  snprintf(buf, len, "%04d-%02d-%02dT%02d:%02d:%02d+08:00",
           tm_buf.tm_year + 1900, tm_buf.tm_mon + 1, tm_buf.tm_mday,
           tm_buf.tm_hour, tm_buf.tm_min, tm_buf.tm_sec);
}

int vg_event_to_json(const vg_safety_event_t *evt, char *buf, size_t len)
{
  char timestr[VG_TIMESTR_LEN];
  size_t pos = 0;
  int n;

  if (evt == NULL || buf == NULL || len < 64)
    {
      return -1;
    }

  vg_format_time(evt->started_at, timestr, sizeof(timestr));

  n = snprintf(buf, len,
               "{\"eventId\":\"%s\",\"deviceId\":\"%s\","
               "\"eventType\":\"%s\",\"level\":\"%s\","
               "\"confidence\":%.2f,\"startedAt\":\"%s\","
               "\"durationSec\":%" PRIu32 ",\"localStatus\":\"%s\","
               "\"uploadReason\":\"%s\",\"timeReliable\":%s,"
               "\"night\":%s",
               evt->event_id, evt->device_id,
               vg_event_type_str(evt->type), vg_level_str(evt->level),
               (double)evt->confidence, timestr,
               evt->duration_sec, vg_status_str(evt->local_status),
               vg_upload_reason_str(evt->upload_reason),
               evt->time_reliable ? "true" : "false",
               evt->night ? "true" : "false");

  if (n < 0 || (size_t)n >= len)
    {
      return -1;
    }

  pos = (size_t)n;

  if (evt->matched_phrase[0] != '\0')
    {
      pos += (size_t)snprintf(buf + pos, len - pos, ",\"matchedPhrase\":");
      pos = vg_json_put_escaped(buf, len, pos, evt->matched_phrase);
    }

  if (evt->person_label[0] != '\0')
    {
      pos += (size_t)snprintf(buf + pos, len - pos, ",\"personLabel\":");
      pos = vg_json_put_escaped(buf, len, pos, evt->person_label);
    }

  if (evt->type == VG_EVT_NAME_CALL_HELP ||
      evt->type == VG_EVT_DISTRESS_VOICE)
    {
      pos += (size_t)snprintf(buf + pos, len - pos,
                              ",\"urgency\":%.2f,\"repeatCount\":%u",
                              (double)evt->urgency,
                              (unsigned)evt->repeat_count);
    }

  if (pos >= len)
    {
      return -1;
    }

  pos += (size_t)snprintf(buf + pos, len - pos, ",\"summary\":");
  pos = vg_json_put_escaped(buf, len, pos, evt->summary);

  if (pos + 2 >= len)
    {
      return -1;
    }

  buf[pos++] = '}';
  buf[pos] = '\0';
  return (int)pos;
}

/* 解析 ISO8601 "YYYY-MM-DDTHH:MM:SS+08:00" 为 Unix 秒 */

static int64_t vg_parse_time(const char *s)
{
  int y;
  int mo;
  int d;
  int h;
  int mi;
  int se;
  int off_h = 8;
  int off_m = 0;
  char sign = '+';
  int64_t days;
  static const int cum[12] =
    {
      0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334
    };

  if (s == NULL)
    {
      return 0;
    }

  if (sscanf(s, "%d-%d-%dT%d:%d:%d%c%d:%d",
             &y, &mo, &d, &h, &mi, &se, &sign, &off_h, &off_m) < 6)
    {
      return 0;
    }

  if (mo < 1 || mo > 12)
    {
      return 0;
    }

  days = (int64_t)(y - 1970) * 365 + ((y - 1969) / 4) - ((y - 1901) / 100) +
         ((y - 1601) / 400) + cum[mo - 1] + (d - 1);

  if (mo > 2 && ((y % 4 == 0 && y % 100 != 0) || y % 400 == 0))
    {
      days += 1;
    }

  return days * 86400 + h * 3600 + mi * 60 + se -
         (sign == '-' ? -1 : 1) * (off_h * 3600 + off_m * 60);
}

int vg_event_from_json(const char *json, vg_safety_event_t *evt)
{
  char tmp[VG_TIMESTR_LEN];
  double d;
  int i;

  if (json == NULL || evt == NULL)
    {
      return -1;
    }

  memset(evt, 0, sizeof(*evt));

  if (vg_json_get_str(json, "eventId", evt->event_id,
                      sizeof(evt->event_id)) < 0)
    {
      return -1;
    }

  vg_json_get_str(json, "deviceId", evt->device_id, sizeof(evt->device_id));

  if (vg_json_get_str(json, "eventType", tmp, sizeof(tmp)) < 0 ||
      vg_event_type_parse(tmp, &evt->type) < 0)
    {
      return -1;
    }

  if (vg_json_get_str(json, "level", tmp, sizeof(tmp)) == 0)
    {
      vg_level_parse(tmp, &evt->level);
    }

  if (vg_json_get_str(json, "localStatus", tmp, sizeof(tmp)) == 0)
    {
      vg_status_parse(tmp, &evt->local_status);
    }

  if (vg_json_get_double(json, "confidence", &d) == 0)
    {
      evt->confidence = (float)d;
    }

  if (vg_json_get_str(json, "startedAt", tmp, sizeof(tmp)) == 0)
    {
      evt->started_at = vg_parse_time(tmp);
    }

  if (vg_json_get_int(json, "durationSec", &i) == 0)
    {
      evt->duration_sec = (uint32_t)i;
    }

  if (vg_json_get_int(json, "repeatCount", &i) == 0)
    {
      evt->repeat_count = (uint16_t)i;
    }

  if (vg_json_get_double(json, "urgency", &d) == 0)
    {
      evt->urgency = (float)d;
    }

  vg_json_get_bool(json, "timeReliable", &evt->time_reliable);
  vg_json_get_bool(json, "night", &evt->night);
  vg_json_get_str(json, "matchedPhrase", evt->matched_phrase,
                  sizeof(evt->matched_phrase));
  vg_json_get_str(json, "personLabel", evt->person_label,
                  sizeof(evt->person_label));
  vg_json_get_str(json, "summary", evt->summary, sizeof(evt->summary));

  return 0;
}

int vg_event_validate(const vg_safety_event_t *evt)
{
  if (evt == NULL)
    {
      return -1;
    }

  if (evt->event_id[0] == '\0')
    {
      return -2;
    }

  if (evt->device_id[0] == '\0')
    {
      return -3;
    }

  if (evt->type < 0 || evt->type >= VG_EVT_TYPE_MAX)
    {
      return -4;
    }

  if (evt->level < VG_LEVEL_NOTICE || evt->level > VG_LEVEL_EMERGENCY)
    {
      return -5;
    }

  if (evt->confidence < 0.0f || evt->confidence > 1.0f)
    {
      return -6;
    }

  if (evt->local_status < 0 || evt->local_status > VG_STATUS_NO_RESPONSE)
    {
      return -7;
    }

  if (evt->upload_reason < 0 || evt->upload_reason > VG_UPLOAD_SYNC)
    {
      return -8;
    }

  return 0;
}

/****************************************************************************
 * 安聆 VelaGuard - 时钟与夜间判定 (PRD-03)
 *
 * 板载 RTC 无备份电池，断电重启后时间不可信。未同步 NTP 时夜间加严规则
 * 自动失效；可选用光感低照度作为夜间旁证。
 ****************************************************************************/

#ifndef __VELAGUARD_VG_TIME_H
#define __VELAGUARD_VG_TIME_H

#include <stdbool.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C"
{
#endif

/* 单调时钟毫秒，用于所有超时与持续时间计算（不受 NTP 校时跳变影响） */

uint64_t vg_now_ms(void);

/* 墙钟 Unix 秒，用于事件时间戳 */

int64_t vg_wall_sec(void);

/* 时间是否可信：系统时间已通过 NTP 同步（或被显式标记为可信） */

bool vg_time_reliable(void);

/* 标记时间已同步 / 失效。板端在 NTP 成功后调用。 */

void vg_time_set_reliable(bool reliable);

/* 启动时自检：系统时间早于 2025-01-01 视为不可信 */

void vg_time_init(void);

/* 光感旁证：持续低照度累计达到阈值时可恢复夜间加严规则。
 * lux < 0 表示无光感数据。
 */

void vg_time_feed_lux(float lux);

/* 当前是否判定为夜间（PRD-03）：
 *  - 时间可信：22:00 — 次日 07:00 为夜间；
 *  - 时间不可信：默认按日间处理，除非光感持续低照度 >= 10 分钟。
 */

bool vg_is_night(void);

/* 夜间判定依据说明，用于 LCD 与日志 */

const char *vg_night_reason(void);

#ifdef __cplusplus
}
#endif

#endif /* __VELAGUARD_VG_TIME_H */

/****************************************************************************
 * 安聆 VelaGuard - 时钟与夜间判定实现 (PRD-03)
 ****************************************************************************/

#include <stdio.h>
#include <string.h>
#include <time.h>

#include "velaguard/vg_time.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define VG_NIGHT_START_HOUR   22
#define VG_NIGHT_END_HOUR     7

/* 光感旁证：持续低照度 10 分钟 */

#define VG_LUX_DARK_THRESHOLD 5.0f
#define VG_LUX_HOLD_MS        (10 * 60 * 1000ULL)

/* 2025-01-01T00:00:00Z，早于此时间认为 RTC 未校准 */

#define VG_TIME_SANE_FLOOR    1735689600LL

/****************************************************************************
 * Private Data
 ****************************************************************************/

static bool     g_time_reliable = false;
static uint64_t g_dark_since_ms = 0;
static bool     g_dark_confirmed = false;
static char     g_night_reason[48] = "时间未同步，按日间标准";

/****************************************************************************
 * Public Functions
 ****************************************************************************/

uint64_t vg_now_ms(void)
{
  struct timespec ts;

  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
    {
      return 0;
    }

  return (uint64_t)ts.tv_sec * 1000ULL + (uint64_t)(ts.tv_nsec / 1000000);
}

int64_t vg_wall_sec(void)
{
  return (int64_t)time(NULL);
}

bool vg_time_reliable(void)
{
  return g_time_reliable;
}

void vg_time_set_reliable(bool reliable)
{
  g_time_reliable = reliable;
}

void vg_time_init(void)
{
  g_time_reliable = (vg_wall_sec() >= VG_TIME_SANE_FLOOR);
  g_dark_since_ms = 0;
  g_dark_confirmed = false;
}

void vg_time_feed_lux(float lux)
{
  uint64_t now = vg_now_ms();

  if (lux < 0.0f)
    {
      /* 无光感数据：清除旁证 */

      g_dark_since_ms = 0;
      g_dark_confirmed = false;
      return;
    }

  if (lux <= VG_LUX_DARK_THRESHOLD)
    {
      if (g_dark_since_ms == 0)
        {
          g_dark_since_ms = now;
        }
      else if (now - g_dark_since_ms >= VG_LUX_HOLD_MS)
        {
          g_dark_confirmed = true;
        }
    }
  else
    {
      g_dark_since_ms = 0;
      g_dark_confirmed = false;
    }
}

bool vg_is_night(void)
{
  if (g_time_reliable)
    {
      time_t t = (time_t)(vg_wall_sec() + 8 * 3600);
      struct tm tm_buf;
      int hour;

      if (gmtime_r(&t, &tm_buf) == NULL)
        {
          strncpy(g_night_reason, "时钟读取失败，按日间标准",
                  sizeof(g_night_reason) - 1);
          return false;
        }

      hour = tm_buf.tm_hour;
      if (hour >= VG_NIGHT_START_HOUR || hour < VG_NIGHT_END_HOUR)
        {
          snprintf(g_night_reason, sizeof(g_night_reason),
                   "时间已同步，当前 %02d 时属夜间", hour);
          return true;
        }

      snprintf(g_night_reason, sizeof(g_night_reason),
               "时间已同步，当前 %02d 时属日间", hour);
      return false;
    }

  if (g_dark_confirmed)
    {
      strncpy(g_night_reason, "时间未同步，光感持续低照度判为夜间",
              sizeof(g_night_reason) - 1);
      g_night_reason[sizeof(g_night_reason) - 1] = '\0';
      return true;
    }

  strncpy(g_night_reason, "时间未同步，夜间加严规则已降级",
          sizeof(g_night_reason) - 1);
  g_night_reason[sizeof(g_night_reason) - 1] = '\0';
  return false;
}

const char *vg_night_reason(void)
{
  return g_night_reason;
}

/****************************************************************************
 * 安聆 VelaGuard - 运行配置 (PRD-03 阈值 / PRD-06 凭证管理)
 *
 * 真实配置存 /data/velaguard/config.json，不进 Git；仓库只提供
 * config.example.json 模板。
 ****************************************************************************/

#ifndef __VELAGUARD_VG_CONFIG_H
#define __VELAGUARD_VG_CONFIG_H

#include <stdbool.h>
#include <stdint.h>

#include "velaguard/vg_types.h"

#ifdef __cplusplus
extern "C"
{
#endif

#define VG_URL_LEN   128
#define VG_PATH_LEN  96

typedef struct
{
  /* 身份与存储 */

  char     device_id[VG_DEVICE_ID_LEN];
  char     data_dir[VG_PATH_LEN];

  /* 通知主通道：局域网控制台 (PRD-06) */

  char     console_host[VG_URL_LEN];
  int      console_port;
  char     console_path[VG_PATH_LEN];

  /* 可选扩展：webhook 转发，失败不影响主通道 */

  char     webhook_url[VG_URL_LEN];
  bool     webhook_enabled;

  /* 演示构建：使用缩短阈值 (PRD-03) */

  bool     demo_mode;

  /* 识别置信度门限 */

  float    conf_alarm_beep;
  float    conf_water_flow;
  float    conf_impact;
  float    conf_distress;
  float    conf_name_call;

  /* 状态机阈值（秒） */

  uint32_t alarm_hold_sec;          /* 报警蜂鸣连续命中 -> 紧急 */
  uint32_t water_notice_sec;        /* 水流 -> 提醒 */
  uint32_t water_warning_sec;       /* 水流 -> 警告 */
  uint32_t warning_countdown_sec;   /* 警告级倒计时 -> 无人响应 */
  uint32_t impact_repeat_window_sec;/* 撞击重复窗口 */
  uint32_t distress_repeat_window_sec;
  uint32_t snooze_minutes;          /* 稍后提醒挂起时长 */
  uint32_t snooze_max_count;        /* 同一事件最多 snooze 次数 */
  uint32_t event_idle_timeout_sec;  /* 持续型事件多久无命中判定结束 */

  /* 上传重试 */

  uint32_t upload_retry_sec;
  uint32_t upload_queue_max;
} vg_config_t;

/* 取全局配置（首次调用返回内置默认值） */

vg_config_t *vg_config(void);

/* 载入默认值 */

void vg_config_defaults(vg_config_t *cfg);

/* 从 JSON 文件载入并覆盖默认值。文件不存在返回 -1（使用默认值继续运行）。 */

int vg_config_load(const char *path);

/* 应用演示模式的缩短阈值（PRD-03：正式阈值 3 分钟，演示构建缩短） */

void vg_config_apply_demo(vg_config_t *cfg);

/* 打印当前配置（不含任何凭证明文） */

void vg_config_dump(void);

#ifdef __cplusplus
}
#endif

#endif /* __VELAGUARD_VG_CONFIG_H */

/****************************************************************************
 * 安聆 VelaGuard - 运行配置实现
 ****************************************************************************/

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "velaguard/vg_config.h"
#include "velaguard/vg_json.h"

/****************************************************************************
 * Private Data
 ****************************************************************************/

static vg_config_t g_config;
static bool        g_config_ready = false;

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void vg_config_defaults(vg_config_t *cfg)
{
  if (cfg == NULL)
    {
      return;
    }

  memset(cfg, 0, sizeof(*cfg));

  strncpy(cfg->device_id, "velaguard_demo_001", sizeof(cfg->device_id) - 1);
  strncpy(cfg->data_dir, "/data/velaguard", sizeof(cfg->data_dir) - 1);
  strncpy(cfg->console_host, "192.168.43.1", sizeof(cfg->console_host) - 1);
  cfg->console_port = 8080;
  strncpy(cfg->console_path, "/events", sizeof(cfg->console_path) - 1);
  cfg->webhook_enabled = false;
  cfg->demo_mode = true;

  cfg->conf_alarm_beep = 0.80f;
  cfg->conf_water_flow = 0.70f;
  cfg->conf_impact     = 0.80f;
  cfg->conf_distress   = 0.70f;
  cfg->conf_name_call  = 0.70f;

  /* PRD-03 演示初始阈值 */

  cfg->alarm_hold_sec             = 5;
  cfg->water_notice_sec           = 30;
  cfg->water_warning_sec          = 120;
  cfg->warning_countdown_sec      = 60;
  cfg->impact_repeat_window_sec   = 60;
  cfg->distress_repeat_window_sec = 60;
  cfg->snooze_minutes             = 10;
  cfg->snooze_max_count           = 2;
  cfg->event_idle_timeout_sec     = 15;

  cfg->upload_retry_sec  = 10;
  cfg->upload_queue_max  = 32;
}

void vg_config_apply_demo(vg_config_t *cfg)
{
  if (cfg == NULL)
    {
      return;
    }

  /* 演示构建缩短阈值，正式部署由 config.json 覆盖为 3 分钟档 */

  cfg->demo_mode             = true;
  cfg->water_notice_sec      = 10;
  cfg->water_warning_sec     = 25;
  cfg->warning_countdown_sec = 15;
  cfg->snooze_minutes        = 1;
}

vg_config_t *vg_config(void)
{
  if (!g_config_ready)
    {
      vg_config_defaults(&g_config);
      g_config_ready = true;
    }

  return &g_config;
}

int vg_config_load(const char *path)
{
  vg_config_t *cfg = vg_config();
  char *buf;
  long size;
  FILE *fp;
  double d;
  int i;

  if (path == NULL)
    {
      return -1;
    }

  fp = fopen(path, "r");
  if (fp == NULL)
    {
      return -1;
    }

  fseek(fp, 0, SEEK_END);
  size = ftell(fp);
  fseek(fp, 0, SEEK_SET);

  if (size <= 0 || size > 16384)
    {
      fclose(fp);
      return -1;
    }

  buf = malloc((size_t)size + 1);
  if (buf == NULL)
    {
      fclose(fp);
      return -1;
    }

  size = (long)fread(buf, 1, (size_t)size, fp);
  buf[size] = '\0';
  fclose(fp);

  vg_json_get_str(buf, "deviceId", cfg->device_id, sizeof(cfg->device_id));
  vg_json_get_str(buf, "dataDir", cfg->data_dir, sizeof(cfg->data_dir));
  vg_json_get_str(buf, "consoleHost", cfg->console_host,
                  sizeof(cfg->console_host));
  vg_json_get_str(buf, "consolePath", cfg->console_path,
                  sizeof(cfg->console_path));
  vg_json_get_str(buf, "webhookUrl", cfg->webhook_url,
                  sizeof(cfg->webhook_url));

  if (vg_json_get_int(buf, "consolePort", &i) == 0)
    {
      cfg->console_port = i;
    }

  vg_json_get_bool(buf, "webhookEnabled", &cfg->webhook_enabled);

  if (vg_json_get_bool(buf, "demoMode", &cfg->demo_mode) == 0 &&
      cfg->demo_mode)
    {
      vg_config_apply_demo(cfg);
    }

#define VG_CFG_F(key, field)                        \
  if (vg_json_get_double(buf, key, &d) == 0)        \
    {                                               \
      cfg->field = (float)d;                        \
    }

#define VG_CFG_U(key, field)                        \
  if (vg_json_get_int(buf, key, &i) == 0 && i >= 0) \
    {                                               \
      cfg->field = (uint32_t)i;                     \
    }

  VG_CFG_F("confAlarmBeep", conf_alarm_beep)
  VG_CFG_F("confWaterFlow", conf_water_flow)
  VG_CFG_F("confImpact", conf_impact)
  VG_CFG_F("confDistress", conf_distress)
  VG_CFG_F("confNameCall", conf_name_call)

  VG_CFG_U("alarmHoldSec", alarm_hold_sec)
  VG_CFG_U("waterNoticeSec", water_notice_sec)
  VG_CFG_U("waterWarningSec", water_warning_sec)
  VG_CFG_U("warningCountdownSec", warning_countdown_sec)
  VG_CFG_U("impactRepeatWindowSec", impact_repeat_window_sec)
  VG_CFG_U("distressRepeatWindowSec", distress_repeat_window_sec)
  VG_CFG_U("snoozeMinutes", snooze_minutes)
  VG_CFG_U("snoozeMaxCount", snooze_max_count)
