/****************************************************************************
 * 安聆 VelaGuard - 本地事件日志 (PRD-05)
 *
 * 限长 100 条，写满后环形覆盖最旧记录；关键记录写入即落盘，断电重启不丢失。
 ****************************************************************************/

#ifndef __VELAGUARD_VG_EVENT_LOG_H
#define __VELAGUARD_VG_EVENT_LOG_H

#include "velaguard/vg_types.h"

#ifdef __cplusplus
extern "C"
{
#endif

/* 初始化并从磁盘恢复。dir 为 NULL 时使用配置中的 data_dir。 */

int vg_event_log_init(const char *dir);

void vg_event_log_deinit(void);

/* 追加一条事件；写满后覆盖最旧记录。成功返回 0。 */

int vg_event_log_append(const vg_safety_event_t *evt);

/* 按 eventId 更新已有记录（状态流转）。未找到返回 -1。 */

int vg_event_log_update(const vg_safety_event_t *evt);

/* 追加或更新：存在则更新，不存在则追加 */

int vg_event_log_put(const vg_safety_event_t *evt);

/* 当前记录条数（<= 100） */

int vg_event_log_count(void);

/* 累计写入条数（含被覆盖的） */

uint32_t vg_event_log_total(void);

/* 按"从新到旧"索引读取，idx = 0 为最新。成功返回 0。 */

int vg_event_log_get(int idx, vg_safety_event_t *out);

/* 按 eventId 查找。成功返回 0。 */

int vg_event_log_find(const char *event_id, vg_safety_event_t *out);

/* 清空日志（含磁盘文件） */

int vg_event_log_clear(void);

/* 导出最近 n 条为 JSON 数组，返回写入字节数 */

int vg_event_log_to_json(int n, char *buf, size_t len);

#ifdef __cplusplus
}
#endif

#endif /* __VELAGUARD_VG_EVENT_LOG_H */

/****************************************************************************
 * 安聆 VelaGuard - 本地事件日志实现 (PRD-05)
 *
 * 采用定长二进制环形文件：头部记录写指针与条数，其后是 100 条定长记录。
 * 每次写入只更新对应槽位与头部并 fsync，避免整文件重写，兼顾 SPI NOR 寿命
 * 与"写入即落盘"要求。
 ****************************************************************************/

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#include "velaguard/vg_config.h"
#include "velaguard/vg_event_log.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define VG_LOG_MAGIC    0x56474c31u  /* "VGL1" */
#define VG_LOG_VERSION  1

/****************************************************************************
 * Private Types
 ****************************************************************************/

typedef struct
{
  uint32_t magic;
  uint32_t version;
  uint32_t capacity;
  uint32_t head;      /* 下一个写入槽位 */
  uint32_t count;     /* 当前有效条数 */
  uint32_t total;     /* 累计写入条数 */
} vg_log_header_t;

/****************************************************************************
 * Private Data
 ****************************************************************************/

static vg_log_header_t   g_hdr;
static vg_safety_event_t g_slots[VG_EVENT_LOG_CAPACITY];
static char              g_log_path[VG_PATH_LEN + 32];
static int               g_fd = -1;
static bool              g_ready = false;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static off_t vg_slot_offset(uint32_t slot)
{
  return (off_t)sizeof(vg_log_header_t) +
         (off_t)slot * (off_t)sizeof(vg_safety_event_t);
}

static int vg_write_header(void)
{
  if (g_fd < 0)
    {
      return -1;
    }

  if (lseek(g_fd, 0, SEEK_SET) < 0 ||
      write(g_fd, &g_hdr, sizeof(g_hdr)) != (ssize_t)sizeof(g_hdr))
    {
      return -1;
    }

  fsync(g_fd);
  return 0;
}

static int vg_write_slot(uint32_t slot)
{
  if (g_fd < 0 || slot >= VG_EVENT_LOG_CAPACITY)
    {
      return -1;
    }

  if (lseek(g_fd, vg_slot_offset(slot), SEEK_SET) < 0 ||
      write(g_fd, &g_slots[slot], sizeof(vg_safety_event_t)) !=
      (ssize_t)sizeof(vg_safety_event_t))
    {
      return -1;
    }

  fsync(g_fd);
  return 0;
}

static void vg_reset_state(void)
{
  memset(&g_hdr, 0, sizeof(g_hdr));
  memset(g_slots, 0, sizeof(g_slots));
  g_hdr.magic = VG_LOG_MAGIC;
  g_hdr.version = VG_LOG_VERSION;
  g_hdr.capacity = VG_EVENT_LOG_CAPACITY;
}

/* 从"最新"索引换算到物理槽位 */

static int vg_slot_of(int idx_from_newest, uint32_t *slot)
{
  int32_t s;

  if (idx_from_newest < 0 || (uint32_t)idx_from_newest >= g_hdr.count)
    {
      return -1;
    }

  s = (int32_t)g_hdr.head - 1 - idx_from_newest;
  while (s < 0)
    {
      s += VG_EVENT_LOG_CAPACITY;
    }

  *slot = (uint32_t)s;
  return 0;
}

static int vg_find_slot(const char *event_id, uint32_t *slot)
{
  uint32_t i;

  if (event_id == NULL || event_id[0] == '\0')
    {
      return -1;
    }

  for (i = 0; i < g_hdr.count; i++)
    {
      uint32_t s;

      if (vg_slot_of((int)i, &s) == 0 &&
          strcmp(g_slots[s].event_id, event_id) == 0)
        {
          *slot = s;
          return 0;
        }
    }

  return -1;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int vg_event_log_init(const char *dir)
{
  const char *base = (dir != NULL) ? dir : vg_config()->data_dir;
  vg_log_header_t disk;

  vg_reset_state();

  mkdir(base, 0755);
  snprintf(g_log_path, sizeof(g_log_path), "%s/events.bin", base);

  g_fd = open(g_log_path, O_RDWR | O_CREAT, 0644);
  if (g_fd < 0)
    {
      /* 存储不可用时降级为纯内存日志，本地提醒能力不受影响 */

      fprintf(stderr, "[velaguard] 事件日志文件不可用(%s)，降级为内存日志\n",
              strerror(errno));
      g_ready = true;
      return -1;
    }

  if (read(g_fd, &disk, sizeof(disk)) == (ssize_t)sizeof(disk) &&
      disk.magic == VG_LOG_MAGIC && disk.version == VG_LOG_VERSION &&
      disk.capacity == VG_EVENT_LOG_CAPACITY &&
      disk.head < VG_EVENT_LOG_CAPACITY &&
      disk.count <= VG_EVENT_LOG_CAPACITY)
    {
      g_hdr = disk;
      if (lseek(g_fd, vg_slot_offset(0), SEEK_SET) >= 0)
        {
          read(g_fd, g_slots, sizeof(g_slots));
        }
    }
  else
    {
      /* 新建或损坏：重建文件 */

      ftruncate(g_fd, 0);
      vg_reset_state();
      vg_write_header();
    }

  g_ready = true;
  return 0;
}

void vg_event_log_deinit(void)
{
  if (g_fd >= 0)
    {
      close(g_fd);
      g_fd = -1;
    }

  g_ready = false;
}

int vg_event_log_append(const vg_safety_event_t *evt)
{
  uint32_t slot;

  if (!g_ready || evt == NULL || vg_event_validate(evt) != 0)
    {
      return -1;
    }

  slot = g_hdr.head;
  g_slots[slot] = *evt;

  g_hdr.head = (g_hdr.head + 1) % VG_EVENT_LOG_CAPACITY;
  if (g_hdr.count < VG_EVENT_LOG_CAPACITY)
    {
      g_hdr.count++;
    }

  g_hdr.total++;

  vg_write_slot(slot);
  vg_write_header();
  return 0;
}

int vg_event_log_update(const vg_safety_event_t *evt)
{
  uint32_t slot;

  if (!g_ready || evt == NULL)
    {
      return -1;
    }

  if (vg_find_slot(evt->event_id, &slot) < 0)
    {
      return -1;
    }

  g_slots[slot] = *evt;
  vg_write_slot(slot);
  return 0;
}

int vg_event_log_put(const vg_safety_event_t *evt)
{
  if (vg_event_log_update(evt) == 0)
    {
      return 0;
    }

  return vg_event_log_append(evt);
}

int vg_event_log_count(void)
{
  return (int)g_hdr.count;
}

uint32_t vg_event_log_total(void)
{
  return g_hdr.total;
}

int vg_event_log_get(int idx, vg_safety_event_t *out)
{
  uint32_t slot;

  if (out == NULL || vg_slot_of(idx, &slot) < 0)
    {
      return -1;
    }

  *out = g_slots[slot];
  return 0;
}

int vg_event_log_find(const char *event_id, vg_safety_event_t *out)
{
  uint32_t slot;

  if (out == NULL || vg_find_slot(event_id, &slot) < 0)
    {
      return -1;
    }

  *out = g_slots[slot];
  return 0;
}

int vg_event_log_clear(void)
{
  vg_reset_state();

  if (g_fd >= 0)
    {
      ftruncate(g_fd, 0);
      vg_write_header();
    }

  return 0;
}

int vg_event_log_to_json(int n, char *buf, size_t len)
{
  size_t pos = 0;
  int i;

  if (buf == NULL || len < 8)
    {
      return -1;
    }

  if (n <= 0 || n > (int)g_hdr.count)
    {
      n = (int)g_hdr.count;
    }

  buf[pos++] = '[';

  for (i = 0; i < n; i++)
    {
      vg_safety_event_t evt;
      int written;

      if (vg_event_log_get(i, &evt) < 0)
        {
          break;
        }

      if (i > 0)
        {
          if (pos + 1 >= len)
            {
              break;
            }

          buf[pos++] = ',';
        }

      written = vg_event_to_json(&evt, buf + pos, len - pos - 2);
      if (written < 0)
        {
          /* 缓冲区不足：回退逗号并结束 */

          if (i > 0)
            {
              pos--;
            }

          break;
        }

      pos += (size_t)written;
    }

  buf[pos++] = ']';
  buf[pos] = '\0';
  return (int)pos;
}

/****************************************************************************
 * 安聆 VelaGuard - 事件状态机与告警规则 (PRD-03)
 *
 * 识别层只给出类别与置信度，是否提醒/升级/通知全部由本模块的可解释规则决定。
 * 本模块不依赖任何硬件，可在模拟器与主机侧单元测试中独立运行。
 ****************************************************************************/

#ifndef __VELAGUARD_VG_EVENT_SM_H
#define __VELAGUARD_VG_EVENT_SM_H

#include "velaguard/vg_types.h"

#ifdef __cplusplus
extern "C"
{
#endif

/* 状态机对外回调：由 main/daemon 装配 UI、日志与通知 */

typedef struct
{
  /* 事件首次产生或状态/等级发生变化 */

  void (*on_event_changed)(const vg_safety_event_t *evt,
                           vg_state_t state, void *arg);

  /* 升级为紧急级、需要远程通知（PRD-06 触发条件） */

  void (*on_escalate)(const vg_safety_event_t *evt, void *arg);

  /* 事件结束（已处理/误报/自动关闭） */

  void (*on_closed)(const vg_safety_event_t *evt, void *arg);

  void *arg;
} vg_sm_cb_t;

/* 单个事件轨道的对外快照 */

typedef struct
{
  vg_safety_event_t evt;
  vg_state_t        state;
  uint32_t          countdown_sec;   /* 警告倒计时剩余秒，0 表示无倒计时 */
  uint32_t          snooze_left_sec; /* snooze 剩余秒 */
  uint32_t          snooze_count;
  bool              notified;
  bool              local_only;      /* 仅本地确认，不升级远程通知 */
} vg_track_view_t;

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

void vg_sm_init(const vg_sm_cb_t *cb);
void vg_sm_reset(void);

/* 识别层输入 (PRD-01) */

void vg_sm_feed_sound(const vg_sound_obs_t *obs);
void vg_sm_feed_distress(const vg_distress_obs_t *obs);

/* 周期驱动：倒计时、snooze 到期、持续事件结束判定。建议 200ms ~ 1s 调用。 */

void vg_sm_tick(void);

/* 本地确认操作 (PRD-04)：handled / false_alarm / snoozed
 * event_id 为 NULL 时作用于当前最高优先级事件。
 * 返回 0 成功，-1 未找到事件，-2 snooze 次数已用尽。
 */

int vg_sm_ack(const char *event_id, vg_local_status_t action);

/* 当前活跃事件数量（未结束） */

int vg_sm_active_count(void);

/* 取最高优先级的活跃事件（PRD-03 并发仲裁）。无活跃事件返回 -1。 */

int vg_sm_top(vg_track_view_t *out);

/* 遍历活跃事件，按优先级从高到低。idx 从 0 开始。 */

int vg_sm_get(int idx, vg_track_view_t *out);

/* 供演示/测试使用：直接注入一个成型的观测（等价于识别层输出） */

void vg_sm_inject(vg_event_type_t type, float confidence,
                  const char *phrase, const char *person,
                  float urgency, uint16_t repeat);

#ifdef __cplusplus
}
#endif

#endif /* __VELAGUARD_VG_EVENT_SM_H */

/****************************************************************************
 * 安聆 VelaGuard - 事件状态机与告警规则实现 (PRD-03)
 ****************************************************************************/

#include <stdio.h>
#include <string.h>

#include "velaguard/vg_config.h"
#include "velaguard/vg_event_log.h"
#include "velaguard/vg_event_sm.h"
#include "velaguard/vg_time.h"

/****************************************************************************
 * Private Types
 ****************************************************************************/

typedef struct
{
  bool              active;
  vg_state_t        state;
  vg_safety_event_t evt;
  bool              materialized;    /* 是否已生成 eventId 并写日志 */
  bool              local_only;      /* 平静单次呼喊：只本地确认不升级 */
  bool              notified;        /* 已触发远程通知 */

  uint64_t          first_hit_ms;
  uint64_t          last_hit_ms;
  uint64_t          state_since_ms;
  uint64_t          deadline_ms;     /* 警告倒计时截止 */
  uint64_t          snooze_deadline_ms;

  uint32_t          snooze_count;
  uint32_t          hit_count;       /* 连续命中窗口数 */
  uint32_t          repeat_count;    /* 瞬态事件重复次数 */
  uint64_t          last_repeat_ms;

  float             conf_peak;
  float             urgency_peak;
} vg_track_t;

/****************************************************************************
 * Private Data
 ****************************************************************************/

static vg_track_t g_tracks[VG_EVT_TYPE_MAX];
static vg_sm_cb_t g_cb;
static uint32_t   g_seq;
static bool       g_inited;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void vg_notify_changed(vg_track_t *t)
{
  if (t->materialized)
    {
      vg_event_log_put(&t->evt);
    }

  if (g_cb.on_event_changed != NULL && t->materialized)
    {
      g_cb.on_event_changed(&t->evt, t->state, g_cb.arg);
    }
}

static void vg_notify_escalate(vg_track_t *t)
{
  if (g_cb.on_escalate != NULL)
    {
      g_cb.on_escalate(&t->evt, g_cb.arg);
    }

  t->notified = true;
}

static void vg_notify_closed(vg_track_t *t)
{
  if (g_cb.on_closed != NULL && t->materialized)
    {
      g_cb.on_closed(&t->evt, g_cb.arg);
    }
}

/* 生成事件摘要（结构化描述，绝不含原始音频或对话文本） */

static void vg_build_summary(vg_track_t *t)
{
  const char *night = t->evt.night ? "夜间" : "";
  vg_safety_event_t *e = &t->evt;

  switch (e->type)
    {
      case VG_EVT_ALARM_BEEP:
        snprintf(e->summary, sizeof(e->summary),
                 "%s检测到疑似烟雾或燃气报警蜂鸣，持续 %" PRIu32 " 秒",
                 night, e->duration_sec);
        break;

      case VG_EVT_WATER_FLOW:
        snprintf(e->summary, sizeof(e->summary),
                 "%s检测到持续水流声，已持续 %" PRIu32 " 秒，疑似忘关水龙头或漏水",
                 night, e->duration_sec);
        break;

      case VG_EVT_IMPACT:
        snprintf(e->summary, sizeof(e->summary),
                 "%s检测到玻璃破碎或重物撞击声%s",
                 night,
                 t->repeat_count > 1 ? "，短时间内重复出现" : "");
        break;

      case VG_EVT_DISTRESS_VOICE:
        snprintf(e->summary, sizeof(e->summary),
                 "%s检测到呻吟或痛苦呼救声，重复 %u 次，%s",
                 night, (unsigned)e->repeat_count,
                 e->local_status == VG_STATUS_NO_RESPONSE ?
                 "用户未确认" : "等待用户确认");
        break;

      case VG_EVT_NAME_CALL_HELP:
        snprintf(e->summary, sizeof(e->summary),
                 "%s检测到%s呼喊%s%s，重复 %u 次，%s",
                 night,
                 e->urgency >= 0.5f ? "急促" : "平静",
                 e->matched_phrase[0] != '\0' ? "「" : "求助内容",
                 e->matched_phrase[0] != '\0' ? e->matched_phrase : "",
                 (unsigned)e->repeat_count,
                 e->local_status == VG_STATUS_NO_RESPONSE ?
                 "用户未确认" : "等待用户确认");

        /* 补上右引号 */

        if (e->matched_phrase[0] != '\0')
          {
            size_t l = strlen(e->summary);
            snprintf(e->summary + l, sizeof(e->summary) - l, "」");
          }
        break;

      default:
        snprintf(e->summary, sizeof(e->summary), "检测到异常声音事件");
        break;
    }
}

static void vg_materialize(vg_track_t *t)
{
  vg_config_t *cfg = vg_config();

  if (t->materialized)
    {
      return;
    }

  snprintf(t->evt.event_id, sizeof(t->evt.event_id),
           "evt_%06" PRIu32, ++g_seq);
  strncpy(t->evt.device_id, cfg->device_id, sizeof(t->evt.device_id) - 1);
  t->evt.local_status = VG_STATUS_PENDING;
  t->evt.upload_reason = VG_UPLOAD_SYNC;
  t->materialized = true;
}

/* 等级提升（只升不降），并处理各级伴随动作 */

static void vg_set_level(vg_track_t *t, vg_level_t level)
{
  vg_config_t *cfg = vg_config();
  uint64_t now = vg_now_ms();

  if (level <= t->evt.level && t->materialized)
    {
      return;
    }

  vg_materialize(t);
  t->evt.level = level;
  t->state_since_ms = now;

  switch (level)
    {
      case VG_LEVEL_NOTICE:
        t->state = VG_STATE_NOTICE;
        t->deadline_ms = 0;
        break;

      case VG_LEVEL_WARNING:
        t->state = VG_STATE_WARNING;
        t->deadline_ms = now + (uint64_t)cfg->warning_countdown_sec * 1000;
        break;

      case VG_LEVEL_EMERGENCY:
        t->state = VG_STATE_EMERGENCY;
        t->deadline_ms = 0;
        break;

      default:
        break;
    }

  vg_build_summary(t);
  vg_notify_changed(t);

  if (level == VG_LEVEL_EMERGENCY && !t->notified && !t->local_only)
    {
      t->evt.upload_reason = VG_UPLOAD_ESCALATED;
      vg_notify_escalate(t);
    }
}

static void vg_track_close(vg_track_t *t, vg_local_status_t status)
{
  t->evt.local_status = status;
  t->state = VG_STATE_CLOSED;
  vg_build_summary(t);
  vg_notify_changed(t);
  vg_notify_closed(t);
  t->active = false;
}

static void vg_track_start(vg_track_t *t, vg_event_type_t type, uint64_t now)
{
  memset(t, 0, sizeof(*t));
  t->active = true;
  t->state = VG_STATE_SUSPECT;
  t->first_hit_ms = now;
  t->last_hit_ms = now;
  t->state_since_ms = now;
  t->evt.type = type;
  t->evt.level = VG_LEVEL_NONE;
  t->evt.started_at = vg_wall_sec();
  t->evt.time_reliable = vg_time_reliable();
  t->evt.night = vg_is_night();
  t->evt.local_status = VG_STATUS_PENDING;
}

static void vg_track_update_duration(vg_track_t *t)
{
  t->evt.duration_sec =
      (uint32_t)((t->last_hit_ms - t->first_hit_ms) / 1000);
}

/****************************************************************************
 * 五类事件规则 (PRD-03)
 ****************************************************************************/

static void vg_rule_alarm_beep(vg_track_t *t)
{
  vg_config_t *cfg = vg_config();
  uint64_t held = t->last_hit_ms - t->first_hit_ms;

  /* 高置信度连续约 5 秒（多个连续窗口确认）-> 直接紧急级 */

  if (held >= (uint64_t)cfg->alarm_hold_sec * 1000 && t->hit_count >= 3)
    {
      vg_set_level(t, VG_LEVEL_EMERGENCY);
    }
  else if (held >= (uint64_t)cfg->alarm_hold_sec * 500)
    {
      vg_set_level(t, VG_LEVEL_WARNING);
    }
}

static void vg_rule_water_flow(vg_track_t *t)
{
  vg_config_t *cfg = vg_config();
  uint64_t held = t->last_hit_ms - t->first_hit_ms;

  if (held >= (uint64_t)cfg->water_warning_sec * 1000)
    {
      vg_set_level(t, VG_LEVEL_WARNING);
    }
  else if (held >= (uint64_t)cfg->water_notice_sec * 1000)
    {
      vg_set_level(t, VG_LEVEL_NOTICE);
    }
}

static void vg_rule_impact(vg_track_t *t)
{
  /* 单次高置信度瞬态 -> 警告；夜间或 60s 内重复 2 次 -> 紧急 */

  if (t->evt.night || t->repeat_count >= 2)
    {
      vg_set_level(t, VG_LEVEL_EMERGENCY);
    }
  else
    {
      vg_set_level(t, VG_LEVEL_WARNING);
    }
}

static void vg_rule_distress(vg_track_t *t)
{
  /* 先本地确认；重复命中或无人响应 -> 升级 */

  if (t->repeat_count >= 2)
    {
      vg_set_level(t, VG_LEVEL_EMERGENCY);
    }
  else
    {
      vg_set_level(t, VG_LEVEL_WARNING);
    }
}

static void vg_rule_name_call(vg_track_t *t)
{
  bool distress_active = g_tracks[VG_EVT_DISTRESS_VOICE].active &&
                         g_tracks[VG_EVT_DISTRESS_VOICE].state !=
                         VG_STATE_CLOSED;

  /* 平静、单次呼喊姓名 -> 只本地确认，不远程通知
   * 急促重复呼喊 / 明确求救词 / 与异常人声组合 -> 升级
   */

  bool urgent = (t->urgency_peak >= 0.5f && t->repeat_count >= 2) ||
                t->evt.repeat_count >= 3 ||
                distress_active;

  if (t->local_only && !urgent)
    {
      vg_set_level(t, VG_LEVEL_NOTICE);
      return;
    }

  t->local_only = false;

  if (t->repeat_count >= 3 || distress_active)
    {
      vg_set_level(t, VG_LEVEL_EMERGENCY);
    }
  else
    {
      vg_set_level(t, VG_LEVEL_WARNING);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void vg_sm_init(const vg_sm_cb_t *cb)
{
  memset(&g_cb, 0, sizeof(g_cb));
  if (cb != NULL)
    {
      g_cb = *cb;
    }

  memset(g_tracks, 0, sizeof(g_tracks));
  g_seq = vg_event_log_total();
  g_inited = true;
}

void vg_sm_reset(void)
{
  memset(g_tracks, 0, sizeof(g_tracks));
  g_seq = vg_event_log_total();
}

void vg_sm_feed_sound(const vg_sound_obs_t *obs)
{
  vg_config_t *cfg = vg_config();
  vg_event_type_t type;
  vg_track_t *t;
  float threshold;
  uint64_t now;

  if (!g_inited || obs == NULL)
    {
      return;
    }

  switch (obs->cls)
    {
      case VG_SOUND_ALARM_BEEP:
        type = VG_EVT_ALARM_BEEP;
        threshold = cfg->conf_alarm_beep;
        break;

      case VG_SOUND_WATER_FLOW:
        type = VG_EVT_WATER_FLOW;
        threshold = cfg->conf_water_flow;
        break;

      case VG_SOUND_IMPACT:
        type = VG_EVT_IMPACT;
        threshold = cfg->conf_impact;
        break;

      default:
        return;
    }

  if (obs->confidence < threshold)
    {
      return;
    }

  now = (obs->ts_ms != 0) ? obs->ts_ms : vg_now_ms();
  t = &g_tracks[type];

  if (!t->active || t->state == VG_STATE_CLOSED)
    {
      /* 已确认为"误报/已处理"的事件在静默期内不重复起新事件 */

      if (t->state == VG_STATE_CLOSED &&
          now - t->state_since_ms <
              (uint64_t)cfg->event_idle_timeout_sec * 1000)
        {
          return;
        }

      vg_track_start(t, type, now);
    }

  t->last_hit_ms = now;
  t->hit_count++;

  if (obs->confidence > t->conf_peak)
    {
      t->conf_peak = obs->confidence;
    }

  t->evt.confidence = t->conf_peak;
  vg_track_update_duration(t);

  if (type == VG_EVT_IMPACT)
    {
      if (t->last_repeat_ms == 0 ||
          now - t->last_repeat_ms <=
              (uint64_t)cfg->impact_repeat_window_sec * 1000)
        {
          t->repeat_count++;
        }
      else
        {
          t->repeat_count = 1;
        }

      t->last_repeat_ms = now;
      t->evt.repeat_count = (uint16_t)t->repeat_count;
    }

  if (t->state == VG_STATE_SNOOZED)
    {
      /* snooze 期间继续统计，但不重新提醒 */

      return;
    }

  switch (type)
    {
      case VG_EVT_ALARM_BEEP:
        vg_rule_alarm_beep(t);
        break;

      case VG_EVT_WATER_FLOW:
        vg_rule_water_flow(t);
        break;

      case VG_EVT_IMPACT:
        vg_rule_impact(t);
        break;

      default:
        break;
    }
}

void vg_sm_feed_distress(const vg_distress_obs_t *obs)
{
  vg_config_t *cfg = vg_config();
  vg_event_type_t type;
  vg_track_t *t;
  float threshold;
  uint64_t now;
  bool calm_single;

  if (!g_inited || obs == NULL || obs->kind == VG_VOICE_NONE)
    {
      return;
    }

  if (obs->kind == VG_VOICE_NAME_CALL || obs->kind == VG_VOICE_HELP_PHRASE)
    {
      type = VG_EVT_NAME_CALL_HELP;
      threshold = cfg->conf_name_call;
    }
  else
    {
      type = VG_EVT_DISTRESS_VOICE;
      threshold = cfg->conf_distress;
    }

  if (obs->confidence < threshold)
    {
      return;
    }

  now = (obs->ts_ms != 0) ? obs->ts_ms : vg_now_ms();
  t = &g_tracks[type];

  if (!t->active || t->state == VG_STATE_CLOSED)
    {
      if (t->state == VG_STATE_CLOSED &&
          now - t->state_since_ms <
              (uint64_t)cfg->event_idle_timeout_sec * 1000)
        {
          return;
        }

      vg_track_start(t, type, now);

      /* 明确求救词一开始就不属于"平静单次呼喊" */

      calm_single = (obs->kind == VG_VOICE_NAME_CALL) &&
                    (obs->urgency < 0.5f);
      t->local_only = (type == VG_EVT_NAME_CALL_HELP) && calm_single;
    }

  t->last_hit_ms = now;
  t->hit_count++;

  if (t->last_repeat_ms == 0 ||
      now - t->last_repeat_ms <=
          (uint64_t)cfg->distress_repeat_window_sec * 1000)
    {
      t->repeat_count++;
    }
  else
    {
      t->repeat_count = 1;
    }

  t->last_repeat_ms = now;

  if (obs->confidence > t->conf_peak)
    {
      t->conf_peak = obs->confidence;
    }

  if (obs->urgency > t->urgency_peak)
    {
      t->urgency_peak = obs->urgency;
    }

  t->evt.confidence = t->conf_peak;
  t->evt.urgency = t->urgency_peak;
  t->evt.repeat_count = (uint16_t)(t->repeat_count + obs->repeat_count);

  if (obs->matched_phrase[0] != '\0')
    {
      strncpy(t->evt.matched_phrase, obs->matched_phrase,
              sizeof(t->evt.matched_phrase) - 1);
    }

  if (obs->person_label[0] != '\0')
    {
      strncpy(t->evt.person_label, obs->person_label,
              sizeof(t->evt.person_label) - 1);
    }

  /* 明确求救短语（含方言）不受"平静单次"豁免 */

  if (obs->kind == VG_VOICE_HELP_PHRASE)
    {
      t->local_only = false;
    }

  vg_track_update_duration(t);

  if (t->state == VG_STATE_SNOOZED)
    {
      return;
    }

  if (type == VG_EVT_NAME_CALL_HELP)
    {
      vg_rule_name_call(t);
    }
  else
    {
      vg_rule_distress(t);
    }
}

void vg_sm_tick(void)
{
  vg_config_t *cfg = vg_config();
  uint64_t now = vg_now_ms();
  int i;

  if (!g_inited)
    {
      return;
    }

  for (i = 0; i < VG_EVT_TYPE_MAX; i++)
    {
      vg_track_t *t = &g_tracks[i];

      if (!t->active)
        {
          continue;
        }

      switch (t->state)
        {
          case VG_STATE_SUSPECT:
            /* 长时间无新命中且未达任何等级 -> 丢弃 */

            if (now - t->last_hit_ms >
                (uint64_t)cfg->event_idle_timeout_sec * 1000)
              {
                t->active = false;
              }
            break;

          case VG_STATE_NOTICE:
            /* 提醒级不做远程升级；长时间无新命中自动收敛 */

            if (now - t->last_hit_ms >
                (uint64_t)cfg->event_idle_timeout_sec * 1000 * 4)
              {
                vg_track_close(t, t->evt.local_status == VG_STATUS_PENDING ?
                                  VG_STATUS_NO_RESPONSE :
                                  t->evt.local_status);
              }
            else if (t->evt.type == VG_EVT_WATER_FLOW)
              {
                vg_track_update_duration(t);
                vg_rule_water_flow(t);
              }
            break;

          case VG_STATE_WARNING:
            if (t->evt.type == VG_EVT_WATER_FLOW &&
                now - t->last_hit_ms <=
                    (uint64_t)cfg->event_idle_timeout_sec * 1000)
              {
                vg_track_update_duration(t);
              }

            /* 倒计时结束、无人确认 -> no_response -> 紧急级 (PRD-03/06) */

            if (t->deadline_ms != 0 && now >= t->deadline_ms)
              {
                t->evt.local_status = VG_STATUS_NO_RESPONSE;

                if (t->local_only)
                  {
                    /* 平静单次呼喊：超时也只关闭，不做远程通知 */

                    vg_track_close(t, VG_STATUS_NO_RESPONSE);
                  }
                else
                  {
                    vg_set_level(t, VG_LEVEL_EMERGENCY);
                  }
              }
            break;

          case VG_STATE_SNOOZED:
            if (now >= t->snooze_deadline_ms)
              {
                /* 到期重新进入警告级倒计时 */

                t->evt.local_status = VG_STATUS_PENDING;
                t->state = VG_STATE_WARNING;
                t->state_since_ms = now;
                t->deadline_ms =
                    now + (uint64_t)cfg->warning_countdown_sec * 1000;
                vg_notify_changed(t);
              }
            break;

          case VG_STATE_EMERGENCY:
            /* 紧急级持续本地提醒，等待用户确认，不自动关闭 */

            if (t->evt.type == VG_EVT_WATER_FLOW &&
                now - t->last_hit_ms <=
                    (uint64_t)cfg->event_idle_timeout_sec * 1000)
              {
                vg_track_update_duration(t);
              }
            break;

          default:
            break;
        }
    }
}

int vg_sm_ack(const char *event_id, vg_local_status_t action)
{
  vg_config_t *cfg = vg_config();
  vg_track_t *t = NULL;
  uint64_t now = vg_now_ms();
  int i;

  if (event_id == NULL || event_id[0] == '\0')
    {
      vg_track_view_t view;

      if (vg_sm_top(&view) < 0)
        {
          return -1;
        }

      event_id = view.evt.event_id;
    }

  for (i = 0; i < VG_EVT_TYPE_MAX; i++)
    {
      if (g_tracks[i].active && g_tracks[i].materialized &&
          strcmp(g_tracks[i].evt.event_id, event_id) == 0)
        {
          t = &g_tracks[i];
          break;
        }
    }

  if (t == NULL)
    {
      return -1;
    }

  switch (action)
    {
      case VG_STATUS_HANDLED:
      case VG_STATUS_FALSE_ALARM:
        /* 用户确认后停止升级；若已发出通知则同步一条最终状态 */

        vg_track_close(t, action);
        return 0;

      case VG_STATUS_SNOOZED:
        if (t->snooze_count >= cfg->snooze_max_count)
          {
            return -2;
          }

        t->snooze_count++;
        t->state = VG_STATE_SNOOZED;
        t->state_since_ms = now;
        t->snooze_deadline_ms =
            now + (uint64_t)cfg->snooze_minutes * 60 * 1000;
        t->evt.local_status = VG_STATUS_SNOOZED;
        vg_notify_changed(t);
        return 0;

      default:
        return -1;
    }
}

int vg_sm_active_count(void)
{
  int n = 0;
  int i;

  for (i = 0; i < VG_EVT_TYPE_MAX; i++)
    {
      if (g_tracks[i].active && g_tracks[i].materialized)
        {
          n++;
        }
    }

  return n;
}

static void vg_fill_view(const vg_track_t *t, vg_track_view_t *out)
{
  uint64_t now = vg_now_ms();

  memset(out, 0, sizeof(*out));
  out->evt = t->evt;
  out->state = t->state;
  out->snooze_count = t->snooze_count;
  out->notified = t->notified;
  out->local_only = t->local_only;

  if (t->state == VG_STATE_WARNING && t->deadline_ms > now)
    {
      out->countdown_sec = (uint32_t)((t->deadline_ms - now + 999) / 1000);
    }

  if (t->state == VG_STATE_SNOOZED && t->snooze_deadline_ms > now)
    {
      out->snooze_left_sec =
          (uint32_t)((t->snooze_deadline_ms - now + 999) / 1000);
    }
}

int vg_sm_get(int idx, vg_track_view_t *out)
{
  const vg_track_t *sorted[VG_EVT_TYPE_MAX];
  int n = 0;
  int i;
  int j;

  if (out == NULL || idx < 0)
    {
      return -1;
    }

  for (i = 0; i < VG_EVT_TYPE_MAX; i++)
    {
      if (g_tracks[i].active && g_tracks[i].materialized)
        {
          sorted[n++] = &g_tracks[i];
        }
    }

  if (idx >= n)
    {
      return -1;
    }

  /* 插入排序：按 PRD-03 展示优先级从高到低 */

  for (i = 1; i < n; i++)
    {
      const vg_track_t *key = sorted[i];

      for (j = i - 1;
           j >= 0 && vg_event_cmp_priority(&sorted[j]->evt, &key->evt) < 0;
           j--)
        {
          sorted[j + 1] = sorted[j];
        }

      sorted[j + 1] = key;
    }

  vg_fill_view(sorted[idx], out);
  return 0;
}

int vg_sm_top(vg_track_view_t *out)
{
  return vg_sm_get(0, out);
}

void vg_sm_inject(vg_event_type_t type, float confidence,
                  const char *phrase, const char *person,
                  float urgency, uint16_t repeat)
{
  uint64_t now = vg_now_ms();

  if (type == VG_EVT_DISTRESS_VOICE || type == VG_EVT_NAME_CALL_HELP)
    {
      vg_distress_obs_t obs;

      memset(&obs, 0, sizeof(obs));
      obs.ts_ms = now;
      obs.confidence = confidence;
      obs.urgency = urgency;
      obs.repeat_count = repeat;

      if (type == VG_EVT_DISTRESS_VOICE)
        {
          obs.kind = VG_VOICE_MOAN;
        }
      else
        {
          obs.kind = (phrase != NULL && phrase[0] != '\0' && urgency >= 0.5f)
                     ? VG_VOICE_HELP_PHRASE : VG_VOICE_NAME_CALL;
        }

      if (phrase != NULL)
        {
          strncpy(obs.matched_phrase, phrase,
                  sizeof(obs.matched_phrase) - 1);
        }

      if (person != NULL)
        {
          strncpy(obs.person_label, person, sizeof(obs.person_label) - 1);
        }

      vg_sm_feed_distress(&obs);
    }
  else
    {
      vg_sound_obs_t obs;

      memset(&obs, 0, sizeof(obs));
      obs.ts_ms = now;
      obs.confidence = confidence;
      obs.window_ms = 1000;

      switch (type)
        {
          case VG_EVT_ALARM_BEEP:
            obs.cls = VG_SOUND_ALARM_BEEP;
            break;

          case VG_EVT_WATER_FLOW:
            obs.cls = VG_SOUND_WATER_FLOW;
            break;

          default:
            obs.cls = VG_SOUND_IMPACT;
            break;
        }

      vg_sm_feed_sound(&obs);
    }
}

