/****************************************************************************
 * 安聆 VelaGuard - 通知器 (PRD-06)
 *
 * notifier 输入 = 结构化事件 + Agent 文案，输出到可配置通道：
 *   主通道（V1 验收）: 局域网控制台 SSE -> 家属手机浏览器
 *   可选扩展        : webhook 转发（失败不影响主通道）
 *
 * LLM/Agent 不可用时使用本地模板文案兜底，绝不因 Agent 失败丢通知。
 ****************************************************************************/

#ifndef __VELAGUARD_VG_NOTIFIER_H
#define __VELAGUARD_VG_NOTIFIER_H

#include "velaguard/vg_types.h"

#ifdef __cplusplus
extern "C"
{
#endif

#define VG_ADVICE_LEN 192

/* Agent 文案提供者：成功返回 0 并填充 advice；失败返回负值触发模板兜底。 */

typedef int (*vg_advice_fn)(const vg_safety_event_t *evt,
                            char *advice, size_t len);

void vg_notifier_init(void);

/* 注册 Agent 文案提供者（anling-home-safety Skill 桥接） */

void vg_notifier_set_advice_provider(vg_advice_fn fn);

/* 生成通知文案：优先 Agent，失败自动回落到本地模板。
 * 返回 0 使用了 Agent 文案，1 使用了模板兜底。
 */

int vg_notifier_build_advice(const vg_safety_event_t *evt,
                             char *advice, size_t len);

/* 本地模板文案（永远可用，不依赖网络与 LLM） */

void vg_notifier_template(const vg_safety_event_t *evt,
                          char *advice, size_t len);

/* 组装通知负载：事件 JSON + advice 字段 */

int vg_notifier_build_payload(const vg_safety_event_t *evt,
                              const char *advice,
                              char *buf, size_t len);

/* 可选扩展通道：webhook 转发。失败返回负值，主通道不受影响。 */

int vg_notifier_webhook(const vg_safety_event_t *evt, const char *advice);

/* 统计：模板兜底次数 / Agent 成功次数 */

void vg_notifier_stats(uint32_t *agent_ok, uint32_t *template_fallback);

#ifdef __cplusplus
}
#endif

#endif /* __VELAGUARD_VG_NOTIFIER_H */

/****************************************************************************
 * 安聆 VelaGuard - 通知器实现 (PRD-06)
 ****************************************************************************/

#include <stdio.h>
#include <string.h>

#include "velaguard/vg_config.h"
#include "velaguard/vg_http.h"
#include "velaguard/vg_json.h"
#include "velaguard/vg_notifier.h"
#include "velaguard/vg_time.h"

/****************************************************************************
 * Private Data
 ****************************************************************************/

static vg_advice_fn g_advice_fn;
static uint32_t     g_agent_ok;
static uint32_t     g_template_fallback;

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void vg_notifier_init(void)
{
  g_advice_fn = NULL;
  g_agent_ok = 0;
  g_template_fallback = 0;
}

void vg_notifier_set_advice_provider(vg_advice_fn fn)
{
  g_advice_fn = fn;
}

void vg_notifier_template(const vg_safety_event_t *evt,
                          char *advice, size_t len)
{
  const char *action;

  if (evt == NULL || advice == NULL || len == 0)
    {
      return;
    }

  switch (evt->type)
    {
      case VG_EVT_ALARM_BEEP:
        action = "疑似烟雾或燃气报警，建议立即电话确认，必要时联系邻居上门查看";
        break;

      case VG_EVT_WATER_FLOW:
        action = "疑似忘关水龙头或漏水，建议电话提醒关闭水阀";
        break;

      case VG_EVT_IMPACT:
        action = "疑似跌倒或物品破碎，建议立即电话确认老人是否受伤";
        break;

      case VG_EVT_DISTRESS_VOICE:
        action = "检测到疑似求助呼喊，建议立即电话确认，无人接听请尽快上门";
        break;

      case VG_EVT_NAME_CALL_HELP:
        action = "检测到急促求助呼喊，建议立即电话确认";
        break;

      default:
        action = "检测到异常声音，建议电话确认家中情况";
        break;
    }

  snprintf(advice, len, "[%s] %s。%s%s",
           vg_level_cn(evt->level), evt->summary, action,
           evt->time_reliable ? "" : "（设备时间未同步，时间仅供参考）");
}

int vg_notifier_build_advice(const vg_safety_event_t *evt,
                             char *advice, size_t len)
{
  if (evt == NULL || advice == NULL || len == 0)
    {
      return -1;
    }

  advice[0] = '\0';

  if (g_advice_fn != NULL && g_advice_fn(evt, advice, len) == 0 &&
      advice[0] != '\0')
    {
      g_agent_ok++;
      return 0;
    }

  /* Agent / LLM 不可用：本地模板兜底，通知照常送达 */

  vg_notifier_template(evt, advice, len);
  g_template_fallback++;
  return 1;
}

int vg_notifier_build_payload(const vg_safety_event_t *evt,
                              const char *advice,
                              char *buf, size_t len)
{
  size_t pos;
  int n;

  if (evt == NULL || buf == NULL || len < 96)
    {
      return -1;
    }

  n = vg_event_to_json(evt, buf, len);
  if (n < 2)
    {
      return -1;
    }

  /* 把结尾的 '}' 换成 ",\"advice\":\"...\"}" */

  pos = (size_t)n - 1;
  pos += (size_t)snprintf(buf + pos, len - pos, ",\"advice\":");
  pos = vg_json_put_escaped(buf, len, pos, advice != NULL ? advice : "");

  if (pos + 2 >= len)
    {
      return -1;
    }

  buf[pos++] = '}';
  buf[pos] = '\0';
  return (int)pos;
}

int vg_notifier_webhook(const vg_safety_event_t *evt, const char *advice)
{
  vg_config_t *cfg = vg_config();
  char host[VG_URL_LEN];
  char path[VG_PATH_LEN];
  char payload[768];
  int port = 80;
  int status = 0;

  if (!cfg->webhook_enabled || cfg->webhook_url[0] == '\0')
    {
      return -1;
    }

  if (vg_http_parse_url(cfg->webhook_url, host, sizeof(host),
                        &port, path, sizeof(path)) < 0)
    {
      return -1;
    }

  if (vg_notifier_build_payload(evt, advice, payload, sizeof(payload)) < 0)
    {
      return -1;
    }

  if (vg_http_post_json(host, port, path, payload, &status, 3000) < 0)
    {
      return -1;
    }

  return (status >= 200 && status < 300) ? 0 : -1;
}

void vg_notifier_stats(uint32_t *agent_ok, uint32_t *template_fallback)
{
  if (agent_ok != NULL)
    {
      *agent_ok = g_agent_ok;
    }

  if (template_fallback != NULL)
    {
      *template_fallback = g_template_fallback;
    }
}

/****************************************************************************
 * 安聆 VelaGuard - 事件上传与断网补发 (PRD-05)
 *
 * 只上传结构化摘要；网络中断不影响本地提醒，恢复后按 eventId 幂等补发。
 ****************************************************************************/

#ifndef __VELAGUARD_VG_UPLOADER_H
#define __VELAGUARD_VG_UPLOADER_H

#include "velaguard/vg_types.h"

#ifdef __cplusplus
extern "C"
{
#endif

int  vg_uploader_init(void);
void vg_uploader_deinit(void);

/* 入队一条待上传摘要（自动生成/复用 Agent 文案）。
 * 同一 eventId 重复入队时覆盖为最新状态，保证幂等。
 */

int vg_uploader_enqueue(const vg_safety_event_t *evt,
                        vg_upload_reason_t reason);

/* 周期驱动：到期重试。建议 1s 调用一次。 */

void vg_uploader_tick(void);

/* 待发送条数 */

int vg_uploader_pending(void);

/* 最近一次上传是否成功（用于 LCD 显示在线状态） */

bool vg_uploader_online(void);

/* 统计：成功 / 失败次数 */

void vg_uploader_stats(uint32_t *sent, uint32_t *failed);

/* 强制立即尝试一次（演示用） */

void vg_uploader_flush(void);

#ifdef __cplusplus
}
#endif

#endif /* __VELAGUARD_VG_UPLOADER_H */

/****************************************************************************
 * 安聆 VelaGuard - 事件上传与断网补发实现 (PRD-05)
 ****************************************************************************/

#include <stdio.h>
#include <string.h>
#include <unistd.h>

#include "velaguard/vg_config.h"
#include "velaguard/vg_http.h"
#include "velaguard/vg_notifier.h"
#include "velaguard/vg_time.h"
#include "velaguard/vg_uploader.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define VG_UPLOAD_QUEUE_MAX 32
#define VG_PAYLOAD_MAX      768

/****************************************************************************
 * Private Types
 ****************************************************************************/

typedef struct
{
  bool     used;
  char     event_id[VG_EVENT_ID_LEN];
  char     payload[VG_PAYLOAD_MAX];
  uint64_t next_try_ms;
  uint32_t attempts;
} vg_upload_item_t;

/****************************************************************************
 * Private Data
 ****************************************************************************/

static vg_upload_item_t g_queue[VG_UPLOAD_QUEUE_MAX];
static char             g_pending_path[VG_PATH_LEN + 32];
static bool             g_online;
static uint32_t         g_sent;
static uint32_t         g_failed;
static bool             g_inited;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* 待发送队列落盘，断电重启后仍能补发（每行一条 payload） */

static void vg_pending_save(void)
{
  FILE *fp;
  int i;

  if (g_pending_path[0] == '\0')
    {
      return;
    }

  fp = fopen(g_pending_path, "w");
  if (fp == NULL)
    {
      return;
    }

  for (i = 0; i < VG_UPLOAD_QUEUE_MAX; i++)
    {
      if (g_queue[i].used)
        {
          fprintf(fp, "%s\n", g_queue[i].payload);
        }
    }

  fflush(fp);
  fileno(fp) >= 0 ? (void)fsync(fileno(fp)) : (void)0;
  fclose(fp);
}

static void vg_pending_load(void)
{
  char line[VG_PAYLOAD_MAX];
  FILE *fp;
  int i = 0;

  if (g_pending_path[0] == '\0')
    {
      return;
    }

  fp = fopen(g_pending_path, "r");
  if (fp == NULL)
    {
      return;
    }

  while (i < VG_UPLOAD_QUEUE_MAX && fgets(line, sizeof(line), fp) != NULL)
    {
      vg_safety_event_t evt;
      size_t len = strlen(line);

      while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
        {
          line[--len] = '\0';
        }

      if (len == 0 || vg_event_from_json(line, &evt) < 0)
        {
          continue;
        }

      g_queue[i].used = true;
      strncpy(g_queue[i].event_id, evt.event_id,
              sizeof(g_queue[i].event_id) - 1);
      strncpy(g_queue[i].payload, line, sizeof(g_queue[i].payload) - 1);
      g_queue[i].next_try_ms = 0;
      g_queue[i].attempts = 0;
      i++;
    }

  fclose(fp);

  if (i > 0)
    {
      printf("[velaguard] 从断点恢复 %d 条待发送通知\n", i);
    }
}

static int vg_try_send(vg_upload_item_t *item)
{
  vg_config_t *cfg = vg_config();
  int status = 0;
  int ret;

  ret = vg_http_post_json(cfg->console_host, cfg->console_port,
                          cfg->console_path, item->payload, &status, 3000);

  if (ret == 0 && status >= 200 && status < 300)
    {
      return 0;
    }

  return -1;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int vg_uploader_init(void)
{
  vg_config_t *cfg = vg_config();

  memset(g_queue, 0, sizeof(g_queue));
  snprintf(g_pending_path, sizeof(g_pending_path),
           "%s/pending.jsonl", cfg->data_dir);

  g_online = false;
  g_sent = 0;
  g_failed = 0;
  g_inited = true;

  vg_pending_load();
  return 0;
}

void vg_uploader_deinit(void)
{
  vg_pending_save();
  g_inited = false;
}

int vg_uploader_enqueue(const vg_safety_event_t *evt,
                        vg_upload_reason_t reason)
{
  vg_safety_event_t local;
  char advice[VG_ADVICE_LEN];
  vg_upload_item_t *slot = NULL;
  int i;

  if (!g_inited || evt == NULL)
    {
      return -1;
    }

  local = *evt;
  local.upload_reason = reason;

  /* 生成通知文案：Agent 优先，失败自动模板兜底 */

  vg_notifier_build_advice(&local, advice, sizeof(advice));

  /* 幂等：同一 eventId 覆盖为最新状态 */

  for (i = 0; i < VG_UPLOAD_QUEUE_MAX; i++)
    {
      if (g_queue[i].used &&
          strcmp(g_queue[i].event_id, local.event_id) == 0)
        {
          slot = &g_queue[i];
          break;
        }
    }

  if (slot == NULL)
    {
      for (i = 0; i < VG_UPLOAD_QUEUE_MAX; i++)
        {
          if (!g_queue[i].used)
            {
              slot = &g_queue[i];
              break;
            }
        }
    }

  if (slot == NULL)
    {
      /* 队列写满：丢弃最旧一条，保证最新高危事件能发出 */

      slot = &g_queue[0];
    }

  memset(slot, 0, sizeof(*slot));
  slot->used = true;
  strncpy(slot->event_id, local.event_id, sizeof(slot->event_id) - 1);

  if (vg_notifier_build_payload(&local, advice, slot->payload,
                                sizeof(slot->payload)) < 0)
    {
      slot->used = false;
      return -1;
    }

  slot->next_try_ms = 0;
  slot->attempts = 0;

  vg_pending_save();

  /* 可选扩展通道：失败不影响主通道 */

  vg_notifier_webhook(&local, advice);

  vg_uploader_tick();
  return 0;
}

void vg_uploader_tick(void)
{
  vg_config_t *cfg = vg_config();
  uint64_t now = vg_now_ms();
  bool changed = false;
  int i;

  if (!g_inited)
    {
      return;
    }

  for (i = 0; i < VG_UPLOAD_QUEUE_MAX; i++)
    {
      vg_upload_item_t *item = &g_queue[i];
      uint32_t backoff;

      if (!item->used || now < item->next_try_ms)
        {
          continue;
        }

      if (vg_try_send(item) == 0)
        {
          item->used = false;
          g_sent++;
          g_online = true;
          changed = true;
          continue;
        }

      item->attempts++;
      g_failed++;
      g_online = false;

      /* 线性退避，封顶 6 倍，保证恢复后能快速补发 */

      backoff = cfg->upload_retry_sec *
                (item->attempts < 6 ? item->attempts : 6);
      item->next_try_ms = now + (uint64_t)backoff * 1000;
    }

  if (changed)
    {
      vg_pending_save();
    }
}

int vg_uploader_pending(void)
{
  int n = 0;
  int i;

  for (i = 0; i < VG_UPLOAD_QUEUE_MAX; i++)
    {
      if (g_queue[i].used)
        {
          n++;
        }
    }

  return n;
}

bool vg_uploader_online(void)
{
  return g_online;
}

void vg_uploader_stats(uint32_t *sent, uint32_t *failed)
{
  if (sent != NULL)
    {
      *sent = g_sent;
    }

  if (failed != NULL)
    {
      *failed = g_failed;
    }
}

void vg_uploader_flush(void)
{
  int i;

  for (i = 0; i < VG_UPLOAD_QUEUE_MAX; i++)
    {
      g_queue[i].next_try_ms = 0;
    }

  vg_uploader_tick();
}

