/****************************************************************************
 * 安聆 VelaGuard - 声学特征提取实现 (PRD-01/07)
 *
 * 与 model/velaguard_features.py 保持逐步骤一致，保证电脑端训练与端侧推理
 * 使用同一套特征定义。
 ****************************************************************************/

#include <math.h>
#include <stdlib.h>
#include <string.h>

#include "velaguard/vg_feature.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define VG_PREEMPH   0.97f
#define VG_MEL_LOW   20.0f
#define VG_MEL_HIGH  7800.0f
#define VG_EPS       1e-10f

#ifndef M_PI
#  define M_PI 3.14159265358979323846
#endif

/****************************************************************************
 * Private Data
 ****************************************************************************/

static float g_hamming[VG_FRAME_LEN];
static float g_mel_fb[VG_NUM_MEL][VG_FFT_SIZE / 2 + 1];
static float g_dct[VG_NUM_MFCC][VG_NUM_MEL];
static int   g_fft_rev[VG_FFT_SIZE];
static float g_cos_tab[VG_FFT_SIZE / 2];
static float g_sin_tab[VG_FFT_SIZE / 2];
static int   g_tables_ready;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static float vg_hz2mel(float hz)
{
  return 2595.0f * log10f(1.0f + hz / 700.0f);
}

static float vg_mel2hz(float mel)
{
  return 700.0f * (powf(10.0f, mel / 2595.0f) - 1.0f);
}

static void vg_build_tables(void)
{
  float mel_low;
  float mel_high;
  float points[VG_NUM_MEL + 2];
  int bins[VG_NUM_MEL + 2];
  int i;
  int j;
  int bits = 0;
  int n = VG_FFT_SIZE;

  if (g_tables_ready)
    {
      return;
    }

  for (i = 0; i < VG_FRAME_LEN; i++)
    {
      g_hamming[i] = 0.54f - 0.46f *
                     cosf(2.0f * (float)M_PI * i / (VG_FRAME_LEN - 1));
    }

  /* FFT 位反转表与旋转因子 */

  while ((1 << bits) < n)
    {
      bits++;
    }

  for (i = 0; i < n; i++)
    {
      int r = 0;

      for (j = 0; j < bits; j++)
        {
          r |= ((i >> j) & 1) << (bits - 1 - j);
        }

      g_fft_rev[i] = r;
    }

  for (i = 0; i < n / 2; i++)
    {
      g_cos_tab[i] = cosf(-2.0f * (float)M_PI * i / n);
      g_sin_tab[i] = sinf(-2.0f * (float)M_PI * i / n);
    }

  /* Mel 滤波器组 */

  mel_low = vg_hz2mel(VG_MEL_LOW);
  mel_high = vg_hz2mel(VG_MEL_HIGH);

  for (i = 0; i < VG_NUM_MEL + 2; i++)
    {
      points[i] = vg_mel2hz(mel_low +
                            (mel_high - mel_low) * i / (VG_NUM_MEL + 1));
      bins[i] = (int)floorf((VG_FFT_SIZE + 1) * points[i] / VG_SAMPLE_RATE);
      if (bins[i] > VG_FFT_SIZE / 2)
        {
          bins[i] = VG_FFT_SIZE / 2;
        }
    }

  memset(g_mel_fb, 0, sizeof(g_mel_fb));
  for (i = 0; i < VG_NUM_MEL; i++)
    {
      for (j = bins[i]; j < bins[i + 1]; j++)
        {
          if (bins[i + 1] > bins[i])
            {
              g_mel_fb[i][j] = (float)(j - bins[i]) /
                               (float)(bins[i + 1] - bins[i]);
            }
        }

      for (j = bins[i + 1]; j < bins[i + 2]; j++)
        {
          if (bins[i + 2] > bins[i + 1])
            {
              g_mel_fb[i][j] = (float)(bins[i + 2] - j) /
                               (float)(bins[i + 2] - bins[i + 1]);
            }
        }
    }

  /* DCT-II 正交化系数 */

  for (i = 0; i < VG_NUM_MFCC; i++)
    {
      for (j = 0; j < VG_NUM_MEL; j++)
        {
          g_dct[i][j] = cosf((float)M_PI * i * (2.0f * j + 1.0f) /
                             (2.0f * VG_NUM_MEL));
        }
    }

  g_tables_ready = 1;
}

/* 就地基 2 FFT，re/im 长度 VG_FFT_SIZE */

static void vg_fft(float *re, float *im)
{
  int n = VG_FFT_SIZE;
  int len;
  int i;

  for (i = 0; i < n; i++)
    {
      int r = g_fft_rev[i];

      if (r > i)
        {
          float t = re[i]; re[i] = re[r]; re[r] = t;
          t = im[i]; im[i] = im[r]; im[r] = t;
        }
    }

  for (len = 2; len <= n; len <<= 1)
    {
      int half = len >> 1;
      int step = n / len;

      for (i = 0; i < n; i += len)
        {
          int k;

          for (k = 0; k < half; k++)
            {
              float wr = g_cos_tab[k * step];
              float wi = g_sin_tab[k * step];
              float xr = re[i + k + half] * wr - im[i + k + half] * wi;
              float xi = re[i + k + half] * wi + im[i + k + half] * wr;

              re[i + k + half] = re[i + k] - xr;
              im[i + k + half] = im[i + k] - xi;
              re[i + k] += xr;
              im[i + k] += xi;
            }
        }
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int vg_feature_mfcc(const int16_t *pcm, size_t nsamples, float *mfcc)
{
  static float re[VG_FFT_SIZE];
  static float im[VG_FFT_SIZE];
  static float mel[VG_NUM_MEL];
  float prev = 0.0f;
  int nframes = 0;
  size_t off;

  if (pcm == NULL || mfcc == NULL || nsamples < VG_FRAME_LEN)
    {
      return -1;
    }

  vg_build_tables();

  for (off = 0;
       off + VG_FRAME_LEN <= nsamples && nframes < VG_MAX_FRAMES;
       off += VG_FRAME_HOP)
    {
      float *out = mfcc + (size_t)nframes * VG_NUM_MFCC;
      int i;
      int j;

      memset(re, 0, sizeof(re));
      memset(im, 0, sizeof(im));

      /* 预加重 + 加窗 */

      prev = (off > 0) ? (float)pcm[off - 1] : 0.0f;
      for (i = 0; i < VG_FRAME_LEN; i++)
        {
          float s = (float)pcm[off + i];

          re[i] = (s - VG_PREEMPH * prev) * g_hamming[i] / 32768.0f;
          prev = s;
        }

      vg_fft(re, im);

      /* 功率谱 -> mel 能量 */

      for (i = 0; i < VG_NUM_MEL; i++)
        {
          float acc = 0.0f;

          for (j = 0; j <= VG_FFT_SIZE / 2; j++)
            {
              float w = g_mel_fb[i][j];

              if (w > 0.0f)
                {
                  acc += w * (re[j] * re[j] + im[j] * im[j]);
                }
            }

          mel[i] = logf(acc + VG_EPS);
        }

      /* DCT -> MFCC */

      for (i = 0; i < VG_NUM_MFCC; i++)
        {
          float acc = 0.0f;

          for (j = 0; j < VG_NUM_MEL; j++)
            {
              acc += mel[j] * g_dct[i][j];
            }

          out[i] = acc / VG_NUM_MEL;
        }

      nframes++;
    }

  return nframes;
}

int vg_feature_extract(const int16_t *pcm, size_t nsamples, float *feat)
{
  static float mfcc[VG_MAX_FRAMES * VG_NUM_MFCC];
  int nframes;
  int i;
  int f;
  size_t k;
  uint32_t zc = 0;

  if (feat == NULL)
    {
      return -1;
    }

  nframes = vg_feature_mfcc(pcm, nsamples, mfcc);
  if (nframes <= 0)
    {
      return -1;
    }

  for (i = 0; i < VG_NUM_MFCC; i++)
    {
      float sum = 0.0f;
      float sum2 = 0.0f;
      float dsum = 0.0f;
      float mean;
      float var;

      for (f = 0; f < nframes; f++)
        {
          float v = mfcc[(size_t)f * VG_NUM_MFCC + i];

          sum += v;
          sum2 += v * v;

          if (f > 0)
            {
              dsum += fabsf(v - mfcc[(size_t)(f - 1) * VG_NUM_MFCC + i]);
            }
        }

      mean = sum / nframes;
      var = sum2 / nframes - mean * mean;
      if (var < 0.0f)
        {
          var = 0.0f;
        }

      feat[i] = mean;
      feat[VG_NUM_MFCC + i] = sqrtf(var);
      feat[VG_NUM_MFCC * 2 + i] =
          (nframes > 1) ? dsum / (nframes - 1) : 0.0f;
    }

  /* 过零率：对瞬态冲击与蜂鸣的区分很有帮助 */

  for (k = 1; k < nsamples; k++)
    {
      if ((pcm[k] >= 0) != (pcm[k - 1] >= 0))
        {
          zc++;
        }
    }

  feat[VG_FEATURE_DIM - 1] = (nsamples > 1)
                             ? (float)zc / (float)(nsamples - 1) : 0.0f;

  return VG_FEATURE_DIM;
}

float vg_feature_energy_db(const int16_t *pcm, size_t nsamples)
{
  double acc = 0.0;
  size_t i;

  if (pcm == NULL || nsamples == 0)
    {
      return -120.0f;
    }

  for (i = 0; i < nsamples; i++)
    {
      double v = (double)pcm[i] / 32768.0;

      acc += v * v;
    }

  acc = sqrt(acc / (double)nsamples);
  return (float)(20.0 * log10(acc + 1e-9));
}

/****************************************************************************
 * 安聆 VelaGuard - 端侧模型定义 (PRD-07)
 *
 * 采用 "MFCC 统计特征 + 两层 MLP" 的轻量方案：无第三方推理运行时、
 * 权重以 C 数组直接编入固件，满足闪存 <= 2MB / 单窗口 < 500ms 的预算，
 * 同时是 PRD-07 降级路线的落地形态。
 *
 * 权重文件 vg_model_weights.c 由 model/train_models.py 自动生成，
 * 请勿手工编辑。
 ****************************************************************************/

#ifndef __VELAGUARD_VG_MODEL_H
#define __VELAGUARD_VG_MODEL_H

#include "velaguard/vg_feature.h"

#ifdef __cplusplus
extern "C"
{
#endif

/* 环境声景分类：other / alarm_beep / water_flow / impact */

#define VG_ENV_CLASSES   4
#define VG_ENV_HIDDEN    24

/* 人声异常检测：none / moan / scream / shout_help */

#define VG_VOICE_CLASSES 4
#define VG_VOICE_HIDDEN  16

/* 由训练脚本生成的权重（int8 量化 + per-tensor scale） */

extern const char  g_vg_model_version[];
extern const char  g_vg_model_trained_on[];

extern const float g_vg_env_mean[VG_FEATURE_DIM];
extern const float g_vg_env_scale[VG_FEATURE_DIM];
extern const signed char g_vg_env_w1[VG_ENV_HIDDEN][VG_FEATURE_DIM];
extern const float g_vg_env_w1_scale;
extern const float g_vg_env_b1[VG_ENV_HIDDEN];
extern const signed char g_vg_env_w2[VG_ENV_CLASSES][VG_ENV_HIDDEN];
extern const float g_vg_env_w2_scale;
extern const float g_vg_env_b2[VG_ENV_CLASSES];

extern const float g_vg_voice_mean[VG_FEATURE_DIM];
extern const float g_vg_voice_scale[VG_FEATURE_DIM];
extern const signed char g_vg_voice_w1[VG_VOICE_HIDDEN][VG_FEATURE_DIM];
extern const float g_vg_voice_w1_scale;
extern const float g_vg_voice_b1[VG_VOICE_HIDDEN];
extern const signed char g_vg_voice_w2[VG_VOICE_CLASSES][VG_VOICE_HIDDEN];
extern const float g_vg_voice_w2_scale;
extern const float g_vg_voice_b2[VG_VOICE_CLASSES];

#ifdef __cplusplus
}
#endif

#endif /* __VELAGUARD_VG_MODEL_H */

/****************************************************************************
 * 安聆 VelaGuard - 端侧分类器 (PRD-01/07)
 ****************************************************************************/

#ifndef __VELAGUARD_VG_CLASSIFIER_H
#define __VELAGUARD_VG_CLASSIFIER_H

#include "velaguard/vg_model.h"
#include "velaguard/vg_types.h"

#ifdef __cplusplus
extern "C"
{
#endif

/* 环境声景分类。probs 至少 VG_ENV_CLASSES 个 float，可为 NULL。
 * 返回 argmax 对应的 vg_sound_class_t。
 */

vg_sound_class_t vg_classify_env(const float *feat, float *probs);

/* 人声异常检测。返回 vg_voice_kind_t（不含 name_call/help_phrase，
 * 后两者由 enrollment 模板匹配产生）。
 */

vg_voice_kind_t vg_classify_voice(const float *feat, float *probs);

/* 模型信息，用于 status 命令与交付材料 */

const char *vg_classifier_info(void);

/* 单次推理耗时统计（微秒），用于 PRD-01 性能验收 */

void vg_classifier_perf(uint32_t *count, uint32_t *avg_us, uint32_t *max_us);
void vg_classifier_perf_reset(void);

#ifdef __cplusplus
}
#endif

#endif /* __VELAGUARD_VG_CLASSIFIER_H */

/****************************************************************************
 * 安聆 VelaGuard - 端侧分类器实现 (PRD-01/07)
 *
 * 两层 MLP，权重 int8 量化 + per-tensor scale 反量化，纯 C 实现，
 * 不引入任何第三方推理运行时。
 ****************************************************************************/

#include <math.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#include "velaguard/vg_classifier.h"

/****************************************************************************
 * Private Data
 ****************************************************************************/

static uint32_t g_infer_count;
static uint64_t g_infer_total_us;
static uint32_t g_infer_max_us;
static char     g_info[128];

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static uint64_t vg_micros(void)
{
  struct timespec ts;

  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
    {
      return 0;
    }

  return (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)(ts.tv_nsec / 1000);
}

static void vg_softmax(float *v, int n)
{
  float max = v[0];
  float sum = 0.0f;
  int i;

  for (i = 1; i < n; i++)
    {
      if (v[i] > max)
        {
          max = v[i];
        }
    }

  for (i = 0; i < n; i++)
    {
      v[i] = expf(v[i] - max);
      sum += v[i];
    }

  if (sum <= 0.0f)
    {
      sum = 1.0f;
    }

  for (i = 0; i < n; i++)
    {
      v[i] /= sum;
    }
}

/* 通用两层 MLP 前向 */

static int vg_mlp_forward(const float *feat,
                          const float *mean, const float *scale,
                          const signed char *w1, float w1_scale,
                          const float *b1, int hidden,
                          const signed char *w2, float w2_scale,
                          const float *b2, int classes,
                          float *probs)
{
  float norm[VG_FEATURE_DIM];
  float h[VG_ENV_HIDDEN > VG_VOICE_HIDDEN ?
          VG_ENV_HIDDEN : VG_VOICE_HIDDEN];
  float out[VG_ENV_CLASSES > VG_VOICE_CLASSES ?
            VG_ENV_CLASSES : VG_VOICE_CLASSES];
  uint64_t t0 = vg_micros();
  uint64_t dt;
  int best = 0;
  int i;
  int j;

  for (i = 0; i < VG_FEATURE_DIM; i++)
    {
      float s = (scale[i] > 1e-6f) ? scale[i] : 1.0f;

      norm[i] = (feat[i] - mean[i]) / s;
    }

  for (i = 0; i < hidden; i++)
    {
      float acc = 0.0f;

      for (j = 0; j < VG_FEATURE_DIM; j++)
        {
          acc += (float)w1[i * VG_FEATURE_DIM + j] * norm[j];
        }

      acc = acc * w1_scale + b1[i];
      h[i] = (acc > 0.0f) ? acc : 0.0f;   /* ReLU */
    }

  for (i = 0; i < classes; i++)
    {
      float acc = 0.0f;

      for (j = 0; j < hidden; j++)
        {
          acc += (float)w2[i * hidden + j] * h[j];
        }

      out[i] = acc * w2_scale + b2[i];
    }

  vg_softmax(out, classes);

  for (i = 1; i < classes; i++)
    {
      if (out[i] > out[best])
        {
          best = i;
        }
    }

  if (probs != NULL)
    {
      memcpy(probs, out, sizeof(float) * (size_t)classes);
    }

  dt = vg_micros() - t0;
  g_infer_count++;
  g_infer_total_us += dt;
  if ((uint32_t)dt > g_infer_max_us)
    {
      g_infer_max_us = (uint32_t)dt;
    }

  return best;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

vg_sound_class_t vg_classify_env(const float *feat, float *probs)
{
  int best;

  if (feat == NULL)
    {
      return VG_SOUND_OTHER;
    }

  best = vg_mlp_forward(feat, g_vg_env_mean, g_vg_env_scale,
                        &g_vg_env_w1[0][0], g_vg_env_w1_scale, g_vg_env_b1,
                        VG_ENV_HIDDEN,
                        &g_vg_env_w2[0][0], g_vg_env_w2_scale, g_vg_env_b2,
                        VG_ENV_CLASSES, probs);

  return (vg_sound_class_t)best;
}

vg_voice_kind_t vg_classify_voice(const float *feat, float *probs)
{
  static const vg_voice_kind_t map[VG_VOICE_CLASSES] =
    {
      VG_VOICE_NONE, VG_VOICE_MOAN, VG_VOICE_SCREAM, VG_VOICE_SHOUT_HELP
    };
  int best;

  if (feat == NULL)
    {
      return VG_VOICE_NONE;
    }

  best = vg_mlp_forward(feat, g_vg_voice_mean, g_vg_voice_scale,
                        &g_vg_voice_w1[0][0], g_vg_voice_w1_scale,
                        g_vg_voice_b1, VG_VOICE_HIDDEN,
                        &g_vg_voice_w2[0][0], g_vg_voice_w2_scale,
                        g_vg_voice_b2, VG_VOICE_CLASSES, probs);

  return map[best];
}

const char *vg_classifier_info(void)
{
  size_t env_bytes = sizeof(g_vg_env_w1) + sizeof(g_vg_env_w2) +
                     sizeof(g_vg_env_b1) + sizeof(g_vg_env_b2) +
                     sizeof(g_vg_env_mean) + sizeof(g_vg_env_scale);
  size_t voice_bytes = sizeof(g_vg_voice_w1) + sizeof(g_vg_voice_w2) +
                       sizeof(g_vg_voice_b1) + sizeof(g_vg_voice_b2) +
                       sizeof(g_vg_voice_mean) + sizeof(g_vg_voice_scale);

  snprintf(g_info, sizeof(g_info),
           "MFCC(%d)+MLP int8 | 版本 %s | 训练集 %s | 权重 %zu 字节",
           VG_FEATURE_DIM, g_vg_model_version, g_vg_model_trained_on,
           env_bytes + voice_bytes);

  return g_info;
}

void vg_classifier_perf(uint32_t *count, uint32_t *avg_us, uint32_t *max_us)
{
  if (count != NULL)
    {
      *count = g_infer_count;
    }

  if (avg_us != NULL)
    {
      *avg_us = (g_infer_count > 0)
                ? (uint32_t)(g_infer_total_us / g_infer_count) : 0;
    }

  if (max_us != NULL)
    {
      *max_us = g_infer_max_us;
    }
}

void vg_classifier_perf_reset(void)
{
  g_infer_count = 0;
  g_infer_total_us = 0;
  g_infer_max_us = 0;
}

