/****************************************************************************
 * 安聆 VelaGuard - 音频采集抽象实现 (PRD-01)
 ****************************************************************************/

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "velaguard/vg_capture.h"
#include "velaguard/vg_feature.h"
#include "velaguard/vg_time.h"

#ifndef CONFIG_VELAGUARD_PCM_DEVICE
#  define CONFIG_VELAGUARD_PCM_DEVICE "/dev/audio/pcm0c"
#endif

/****************************************************************************
 * Private Types
 ****************************************************************************/

typedef struct
{
  uint16_t channels;
  uint32_t rate;
  uint16_t bits;
  long     data_off;
  long     data_len;
} vg_wav_info_t;

/****************************************************************************
 * Private Data
 ****************************************************************************/

static vg_source_t g_source = VG_SRC_NONE;
static FILE       *g_wav;
static vg_wav_info_t g_wav_info;
static long        g_wav_pos;
static int         g_mic_fd = -1;
static bool        g_paused;
static char        g_pause_reason[48];
static uint64_t    g_hold_until_ms;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static uint32_t vg_rd32(const unsigned char *p)
{
  return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
         ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

static uint16_t vg_rd16(const unsigned char *p)
{
  return (uint16_t)((uint16_t)p[0] | ((uint16_t)p[1] << 8));
}

static int vg_wav_parse(FILE *fp, vg_wav_info_t *info)
{
  unsigned char hdr[12];
  unsigned char chunk[8];

  if (fread(hdr, 1, sizeof(hdr), fp) != sizeof(hdr) ||
      memcmp(hdr, "RIFF", 4) != 0 || memcmp(hdr + 8, "WAVE", 4) != 0)
    {
      return -1;
    }

  memset(info, 0, sizeof(*info));

  while (fread(chunk, 1, sizeof(chunk), fp) == sizeof(chunk))
    {
      uint32_t size = vg_rd32(chunk + 4);
      long next = ftell(fp) + (long)size + (size & 1);

      if (memcmp(chunk, "fmt ", 4) == 0 && size >= 16)
        {
          unsigned char fmt[16];

          if (fread(fmt, 1, sizeof(fmt), fp) != sizeof(fmt))
            {
              return -1;
            }

          info->channels = vg_rd16(fmt + 2);
          info->rate = vg_rd32(fmt + 4);
          info->bits = vg_rd16(fmt + 14);
        }
      else if (memcmp(chunk, "data", 4) == 0)
        {
          info->data_off = ftell(fp);
          info->data_len = (long)size;
          break;
        }

      if (fseek(fp, next, SEEK_SET) != 0)
        {
          break;
        }
    }

  if (info->data_off == 0 || info->channels == 0 || info->rate == 0)
    {
      return -1;
    }

  if (info->bits != 16)
    {
      fprintf(stderr, "[velaguard] 仅支持 16bit wav（当前 %ubit），"
                      "请先用 model/prepare_dataset.py 转换\n",
              (unsigned)info->bits);
      return -1;
    }

  return 0;
}

/* 从 wav 读取并重采样为 16kHz 单声道 */

static int vg_wav_read(int16_t *buf, size_t nsamples)
{
  size_t produced = 0;
  int16_t frame[8];

  while (produced < nsamples)
    {
      /* 线性最近邻重采样：按目标索引换算源索引 */

      double ratio = (double)g_wav_info.rate / (double)VG_SAMPLE_RATE;
      long src_index = (long)((double)g_wav_pos * ratio);
      long byte_off = g_wav_info.data_off +
                      src_index * 2 * (long)g_wav_info.channels;
      size_t framebytes = 2 * (size_t)g_wav_info.channels;
      int32_t acc = 0;
      int c;

      if (byte_off + (long)framebytes >
          g_wav_info.data_off + g_wav_info.data_len)
        {
          break;
        }

      if (fseek(g_wav, byte_off, SEEK_SET) != 0 ||
          fread(frame, 1, framebytes, g_wav) != framebytes)
        {
          break;
        }

      for (c = 0; c < (int)g_wav_info.channels && c < 8; c++)
        {
          acc += frame[c];
        }

      buf[produced++] = (int16_t)(acc / (int)g_wav_info.channels);
      g_wav_pos++;
    }

  return (int)produced;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int vg_capture_open(vg_source_t src, const char *path)
{
  vg_capture_close();

  switch (src)
    {
      case VG_SRC_WAV:
        if (path == NULL)
          {
            return -1;
          }

        g_wav = fopen(path, "rb");
        if (g_wav == NULL)
          {
            fprintf(stderr, "[velaguard] 打开 wav 失败: %s\n", path);
            return -1;
          }

        if (vg_wav_parse(g_wav, &g_wav_info) < 0)
          {
            fclose(g_wav);
            g_wav = NULL;
            return -1;
          }

        g_wav_pos = 0;
        g_source = VG_SRC_WAV;
        printf("[velaguard] 音频源: wav %s (%uHz %uch)\n",
               path, (unsigned)g_wav_info.rate,
               (unsigned)g_wav_info.channels);
        return 0;

      case VG_SRC_MIC:
        g_mic_fd = open(path != NULL ? path : CONFIG_VELAGUARD_PCM_DEVICE,
                        O_RDONLY);
        if (g_mic_fd < 0)
          {
            fprintf(stderr,
                    "[velaguard] 麦克风设备不可用(%s)。"
                    "模拟器线请使用 wav 音频源或模拟事件注入。\n",
                    strerror(errno));
            return -1;
          }

        g_source = VG_SRC_MIC;
        printf("[velaguard] 音频源: 板载麦克风 %s\n",
               path != NULL ? path : CONFIG_VELAGUARD_PCM_DEVICE);
        return 0;

      default:
        g_source = VG_SRC_NONE;
        return 0;
    }
}

int vg_capture_read(int16_t *buf, size_t nsamples)
{
  if (buf == NULL || nsamples == 0)
    {
      return -1;
    }

  if (g_hold_until_ms != 0)
    {
      if (vg_now_ms() < g_hold_until_ms)
        {
          return 0;
        }

      g_hold_until_ms = 0;
    }

  if (g_paused)
    {
      return 0;
    }

  switch (g_source)
    {
      case VG_SRC_WAV:
        return vg_wav_read(buf, nsamples);

      case VG_SRC_MIC:
        {
          ssize_t n = read(g_mic_fd, buf, nsamples * sizeof(int16_t));

          if (n <= 0)
            {
              return (int)n;
            }

          return (int)(n / (ssize_t)sizeof(int16_t));
        }

      default:
        return 0;
    }
}

void vg_capture_close(void)
{
  if (g_wav != NULL)
    {
      fclose(g_wav);
      g_wav = NULL;
    }

  if (g_mic_fd >= 0)
    {
      close(g_mic_fd);
      g_mic_fd = -1;
    }

  g_source = VG_SRC_NONE;
}

vg_source_t vg_capture_source(void)
{
  return g_source;
}

const char *vg_capture_source_name(void)
{
  switch (g_source)
    {
      case VG_SRC_MIC:
        return "板载麦克风";

      case VG_SRC_WAV:
        return "wav 回放";

      default:
        return "无音频源(模拟注入)";
    }
}

void vg_capture_pause(const char *reason)
{
  g_paused = true;
  strncpy(g_pause_reason, reason != NULL ? reason : "守护已暂停",
          sizeof(g_pause_reason) - 1);
  g_pause_reason[sizeof(g_pause_reason) - 1] = '\0';
}

void vg_capture_resume(void)
{
  g_paused = false;
  g_pause_reason[0] = '\0';
}

bool vg_capture_paused(void)
{
  return g_paused;
}

const char *vg_capture_pause_reason(void)
{
  return g_pause_reason[0] != '\0' ? g_pause_reason : "守护中";
}

void vg_capture_hold_for_playback(uint32_t max_ms)
{
  /* PRD-04：不支持录放并发时的时分方案，单次中断上限 2 秒 */

  if (max_ms > 2000)
    {
      max_ms = 2000;
    }

  g_hold_until_ms = vg_now_ms() + max_ms;
}

void vg_capture_release_playback(void)
{
  g_hold_until_ms = 0;
}

/****************************************************************************
 * 安聆 VelaGuard - 个性化录入与模板匹配 (PRD-02)
 *
 * 只保存声学特征模板与预设显示名称，绝不保存原始录音；
 * 支持查看、重录、删除，删除立即生效且不可恢复。
 ****************************************************************************/

#ifndef __VELAGUARD_VG_ENROLL_H
#define __VELAGUARD_VG_ENROLL_H

#include "velaguard/vg_feature.h"
#include "velaguard/vg_types.h"

#ifdef __cplusplus
extern "C"
{
#endif

#define VG_TEMPLATE_MAX      16
#define VG_ENROLL_MIN_TAKES  3
#define VG_ENROLL_MAX_TAKES  5

/* 模板类别 */

typedef enum
{
  VG_TPL_NAME = 0,     /* 姓名 / 昵称 / 亲属称呼 */
  VG_TPL_HELP,         /* 明确求救短语 */
  VG_TPL_DIALECT,      /* 方言求救短语 */
  VG_TPL_KIND_MAX
} vg_tpl_kind_t;

/* 表达方式：同一短语需成对录制（PRD-02） */

typedef enum
{
  VG_TPL_CALM = 0,
  VG_TPL_URGENT
} vg_tpl_style_t;

typedef struct
{
  bool           used;
  vg_tpl_kind_t  kind;
  vg_tpl_style_t style;
  char           phrase[VG_PHRASE_LEN];   /* 预设短语标签 */
  char           person[VG_LABEL_LEN];    /* 预设人员标签 */
  uint8_t        takes;                   /* 已合并的采集次数 */
  float          centroid[VG_FEATURE_DIM];
  float          radius;                  /* 匹配半径 */
} vg_template_t;

typedef struct
{
  bool           hit;
  int            index;
  float          score;      /* 0~1，越大越像 */
  vg_tpl_kind_t  kind;
  vg_tpl_style_t style;
  char           phrase[VG_PHRASE_LEN];
  char           person[VG_LABEL_LEN];
} vg_enroll_match_t;

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

int  vg_enroll_init(const char *dir);
void vg_enroll_deinit(void);

/* 预设标签目录（板端无键盘，只能从预设中选择或自动编号） */

int         vg_enroll_preset_person_count(void);
const char *vg_enroll_preset_person(int idx);
int         vg_enroll_preset_phrase_count(vg_tpl_kind_t kind);
const char *vg_enroll_preset_phrase(vg_tpl_kind_t kind, int idx);

/* 录入流程：begin -> feed x(3~5) -> commit / cancel
 * 录入期间守护采集暂停（调用方负责 vg_capture_pause）。
 */

int  vg_enroll_begin(vg_tpl_kind_t kind, vg_tpl_style_t style,
                     const char *phrase, const char *person);
int  vg_enroll_feed(const float *feat);
int  vg_enroll_takes(void);
int  vg_enroll_commit(void);
void vg_enroll_cancel(void);
bool vg_enroll_active(void);

/* 管理 */

int  vg_enroll_count(void);
int  vg_enroll_get(int idx, vg_template_t *out);
int  vg_enroll_delete(int idx);
int  vg_enroll_clear(void);

/* 匹配：命中返回 0 并填充 out；未命中返回 -1。 */

int  vg_enroll_match(const float *feat, vg_enroll_match_t *out);

/* PRD-02 演示最小集自检：2 成员 + 2 姓名/称呼 + 3 求救短语 + 1 方言，
 * 且每条短语平静/急促成对。ready 返回 true，否则 why 说明缺什么。
 */

bool vg_enroll_min_set_ready(char *why, size_t len);

#ifdef __cplusplus
}
#endif

#endif /* __VELAGUARD_VG_ENROLL_H */

/****************************************************************************
 * 安聆 VelaGuard - 个性化录入与模板匹配实现 (PRD-02)
 *
 * 模板 = 3~5 次采集特征的质心 + 匹配半径；匹配用归一化欧氏距离。
 * 该方案是 PRD-07 "通用关键词模型不稳定时的保底路线"，无需任何推理框架。
 ****************************************************************************/

#include <fcntl.h>
#include <math.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#include "velaguard/vg_config.h"
#include "velaguard/vg_enroll.h"
#include "velaguard/vg_model.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define VG_TPL_MAGIC   0x56475431u   /* "VGT1" */

/* 匹配判定：距离小于半径即命中，score 由距离线性映射 */

#define VG_MATCH_MARGIN 1.25f

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const char * const g_preset_person[] =
{
  "家庭成员 A", "家庭成员 B", "家庭成员 C", "老伴", "儿子", "女儿"
};

static const char * const g_preset_name[] =
{
  "姓名/昵称", "老伴", "妈妈", "爸爸", "奶奶", "爷爷"
};

static const char * const g_preset_help[] =
{
  "救命", "快来人", "来人啊", "我摔倒了", "帮帮我"
};

static const char * const g_preset_dialect[] =
{
  "救命啊(方言)", "来人咯(方言)", "疼死了(方言)"
};

static vg_template_t g_templates[VG_TEMPLATE_MAX];
static char          g_tpl_path[VG_PATH_LEN + 32];

/* 录入会话状态 */

static bool           g_enroll_active;
static vg_template_t  g_pending;
static float          g_takes[VG_ENROLL_MAX_TAKES][VG_FEATURE_DIM];
static int            g_take_count;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* 用环境模型的归一化参数把特征拉到同一尺度，避免个别维度主导距离 */

static void vg_normalize(const float *feat, float *out)
{
  int i;

  for (i = 0; i < VG_FEATURE_DIM; i++)
    {
      float s = (g_vg_env_scale[i] > 1e-6f) ? g_vg_env_scale[i] : 1.0f;

      out[i] = (feat[i] - g_vg_env_mean[i]) / s;
    }
}

static float vg_distance(const float *a, const float *b)
{
  float acc = 0.0f;
  int i;

  for (i = 0; i < VG_FEATURE_DIM; i++)
    {
      float d = a[i] - b[i];

      acc += d * d;
    }

  return sqrtf(acc / VG_FEATURE_DIM);
}

static int vg_tpl_save(void)
{
  uint32_t magic = VG_TPL_MAGIC;
  int fd;

  if (g_tpl_path[0] == '\0')
    {
      return -1;
    }

  fd = open(g_tpl_path, O_WRONLY | O_CREAT | O_TRUNC, 0600);
  if (fd < 0)
    {
      return -1;
    }

  write(fd, &magic, sizeof(magic));
  write(fd, g_templates, sizeof(g_templates));
  fsync(fd);
  close(fd);
  return 0;
}

static int vg_tpl_load(void)
{
  uint32_t magic = 0;
  int fd;

  fd = open(g_tpl_path, O_RDONLY);
  if (fd < 0)
    {
      return -1;
    }

  if (read(fd, &magic, sizeof(magic)) != (ssize_t)sizeof(magic) ||
      magic != VG_TPL_MAGIC ||
      read(fd, g_templates, sizeof(g_templates)) !=
      (ssize_t)sizeof(g_templates))
    {
      memset(g_templates, 0, sizeof(g_templates));
      close(fd);
      return -1;
    }

  close(fd);
  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int vg_enroll_init(const char *dir)
{
  const char *base = (dir != NULL) ? dir : vg_config()->data_dir;

  memset(g_templates, 0, sizeof(g_templates));
  g_enroll_active = false;
  g_take_count = 0;

  mkdir(base, 0755);
  snprintf(g_tpl_path, sizeof(g_tpl_path), "%s/templates.bin", base);
  vg_tpl_load();
  return 0;
}

void vg_enroll_deinit(void)
{
  g_enroll_active = false;
}

int vg_enroll_preset_person_count(void)
{
  return (int)(sizeof(g_preset_person) / sizeof(g_preset_person[0]));
}

const char *vg_enroll_preset_person(int idx)
{
  if (idx < 0 || idx >= vg_enroll_preset_person_count())
    {
      return "";
    }

  return g_preset_person[idx];
}

int vg_enroll_preset_phrase_count(vg_tpl_kind_t kind)
{
  switch (kind)
    {
      case VG_TPL_NAME:
        return (int)(sizeof(g_preset_name) / sizeof(g_preset_name[0]));

      case VG_TPL_HELP:
        return (int)(sizeof(g_preset_help) / sizeof(g_preset_help[0]));

      case VG_TPL_DIALECT:
        return (int)(sizeof(g_preset_dialect) / sizeof(g_preset_dialect[0]));

      default:
        return 0;
    }
}

const char *vg_enroll_preset_phrase(vg_tpl_kind_t kind, int idx)
{
  if (idx < 0 || idx >= vg_enroll_preset_phrase_count(kind))
    {
      return "";
    }

  switch (kind)
    {
      case VG_TPL_NAME:
        return g_preset_name[idx];

      case VG_TPL_HELP:
        return g_preset_help[idx];

      default:
        return g_preset_dialect[idx];
    }
}

int vg_enroll_begin(vg_tpl_kind_t kind, vg_tpl_style_t style,
                    const char *phrase, const char *person)
{
  if (kind < 0 || kind >= VG_TPL_KIND_MAX)
    {
      return -1;
    }

  memset(&g_pending, 0, sizeof(g_pending));
  g_pending.kind = kind;
  g_pending.style = style;

  strncpy(g_pending.phrase,
          (phrase != NULL && phrase[0] != '\0') ?
          phrase : vg_enroll_preset_phrase(kind, 0),
          sizeof(g_pending.phrase) - 1);
  strncpy(g_pending.person,
          (person != NULL && person[0] != '\0') ?
          person : vg_enroll_preset_person(0),
          sizeof(g_pending.person) - 1);

  g_take_count = 0;
  g_enroll_active = true;
  return 0;
}

int vg_enroll_feed(const float *feat)
{
  if (!g_enroll_active || feat == NULL)
    {
      return -1;
    }

  if (g_take_count >= VG_ENROLL_MAX_TAKES)
    {
      return -2;
    }

  vg_normalize(feat, g_takes[g_take_count]);
  g_take_count++;
  return g_take_count;
}

int vg_enroll_takes(void)
{
  return g_take_count;
}

bool vg_enroll_active(void)
{
  return g_enroll_active;
}

int vg_enroll_commit(void)
{
  float maxd = 0.0f;
  int slot = -1;
  int i;
  int j;

  if (!g_enroll_active)
    {
      return -1;
    }

  if (g_take_count < VG_ENROLL_MIN_TAKES)
    {
      return -2;
    }

  /* 同一 (kind, phrase, person, style) 视为重录，直接覆盖 */

  for (i = 0; i < VG_TEMPLATE_MAX; i++)
    {
      if (g_templates[i].used &&
          g_templates[i].kind == g_pending.kind &&
          g_templates[i].style == g_pending.style &&
          strcmp(g_templates[i].phrase, g_pending.phrase) == 0 &&
          strcmp(g_templates[i].person, g_pending.person) == 0)
        {
          slot = i;
          break;
        }
    }

  if (slot < 0)
    {
      for (i = 0; i < VG_TEMPLATE_MAX; i++)
        {
          if (!g_templates[i].used)
            {
              slot = i;
              break;
            }
        }
    }

  if (slot < 0)
    {
      g_enroll_active = false;
      return -3;
    }

  /* 质心 */

  for (j = 0; j < VG_FEATURE_DIM; j++)
    {
      float sum = 0.0f;

      for (i = 0; i < g_take_count; i++)
        {
          sum += g_takes[i][j];
        }

      g_pending.centroid[j] = sum / g_take_count;
    }

  /* 半径：采集样本到质心的最大距离，留出裕度 */

  for (i = 0; i < g_take_count; i++)
    {
      float d = vg_distance(g_takes[i], g_pending.centroid);

      if (d > maxd)
        {
          maxd = d;
        }
    }

  g_pending.radius = (maxd > 1e-4f) ? maxd * VG_MATCH_MARGIN : 0.35f;
  g_pending.takes = (uint8_t)g_take_count;
  g_pending.used = true;

  g_templates[slot] = g_pending;
  g_enroll_active = false;
  g_take_count = 0;

  vg_tpl_save();
  return slot;
}

void vg_enroll_cancel(void)
{
  g_enroll_active = false;
  g_take_count = 0;
  memset(&g_pending, 0, sizeof(g_pending));
}

int vg_enroll_count(void)
{
  int n = 0;
  int i;

  for (i = 0; i < VG_TEMPLATE_MAX; i++)
    {
      if (g_templates[i].used)
        {
          n++;
        }
    }

  return n;
}

int vg_enroll_get(int idx, vg_template_t *out)
{
  int n = 0;
  int i;

  if (out == NULL || idx < 0)
    {
      return -1;
    }

  for (i = 0; i < VG_TEMPLATE_MAX; i++)
    {
      if (g_templates[i].used && n++ == idx)
        {
          *out = g_templates[i];
          return i;
        }
    }

  return -1;
}

int vg_enroll_delete(int idx)
{
  vg_template_t tmp;
  int slot = vg_enroll_get(idx, &tmp);

  if (slot < 0)
    {
      return -1;
    }

  /* 立即生效且不可恢复：清零后落盘 */

  memset(&g_templates[slot], 0, sizeof(g_templates[slot]));
  vg_tpl_save();
  return 0;
}

int vg_enroll_clear(void)
{
  memset(g_templates, 0, sizeof(g_templates));
  vg_tpl_save();
  return 0;
}

int vg_enroll_match(const float *feat, vg_enroll_match_t *out)
{
  float norm[VG_FEATURE_DIM];
  float best_score = 0.0f;
  int best = -1;
  int i;

  if (feat == NULL || out == NULL)
    {
      return -1;
    }

  memset(out, 0, sizeof(*out));
  vg_normalize(feat, norm);

  for (i = 0; i < VG_TEMPLATE_MAX; i++)
    {
      float d;
      float score;

      if (!g_templates[i].used)
        {
          continue;
        }

      d = vg_distance(norm, g_templates[i].centroid);
      if (d >= g_templates[i].radius)
        {
          continue;
        }

      score = 1.0f - d / g_templates[i].radius;
      if (score > best_score)
        {
          best_score = score;
          best = i;
        }
    }

  if (best < 0)
    {
      return -1;
    }

  out->hit = true;
  out->index = best;
  out->score = best_score;
  out->kind = g_templates[best].kind;
  out->style = g_templates[best].style;
  strncpy(out->phrase, g_templates[best].phrase, sizeof(out->phrase) - 1);
  strncpy(out->person, g_templates[best].person, sizeof(out->person) - 1);
  return 0;
}

bool vg_enroll_min_set_ready(char *why, size_t len)
{
  bool person_seen[8] = { false };
  int persons = 0;
  int names = 0;
  int helps = 0;
  int dialects = 0;
  int unpaired = 0;
  int i;
  int j;

  for (i = 0; i < VG_TEMPLATE_MAX; i++)
    {
      const vg_template_t *t = &g_templates[i];
      bool paired = false;

      if (!t->used)
        {
          continue;
        }

      for (j = 0; j < vg_enroll_preset_person_count() && j < 8; j++)
        {
          if (strcmp(t->person, vg_enroll_preset_person(j)) == 0 &&
              !person_seen[j])
            {
              person_seen[j] = true;
              persons++;
              break;
            }
        }

      switch (t->kind)
        {
          case VG_TPL_NAME:
            names++;
            break;

          case VG_TPL_HELP:
            helps++;
            break;

          default:
            dialects++;
            break;
        }

      /* 平静/急促成对检查 */

      for (j = 0; j < VG_TEMPLATE_MAX; j++)
        {
          if (j != i && g_templates[j].used &&
              g_templates[j].kind == t->kind &&
              g_templates[j].style != t->style &&
              strcmp(g_templates[j].phrase, t->phrase) == 0)
            {
              paired = true;
              break;
            }
        }

      if (!paired)
        {
          unpaired++;
        }
    }

  /* 成对统计时每条短语被计两次，这里按条目数折算 */

  if (persons >= 2 && names >= 2 && helps >= 3 && dialects >= 1 &&
      unpaired == 0)
    {
      if (why != NULL && len > 0)
        {
          snprintf(why, len, "录入最小集已满足（%d 条模板）",
                   vg_enroll_count());
        }

      return true;
    }

  if (why != NULL && len > 0)
    {
      snprintf(why, len,
               "缺: 成员%d/2 称呼%d/2 求救词%d/3 方言%d/1 未成对%d",
               persons, names, helps, dialects, unpaired);
    }

  return false;
}

/****************************************************************************
 * 安聆 VelaGuard - 声学识别引擎调度 (PRD-01)
 *
 * 三条识别通道并行工作于同一个 1 秒窗口（50% 重叠）：
 *   1. 环境声景分类   -> SoundObservation
 *   2. 人声异常检测   -> DistressObservation
 *   3. 个性化模板匹配 -> DistressObservation(name_call / help_phrase)
 *
 * 本模块只输出类别与置信度，不做任何告警决策（决策在 PRD-03 状态机）。
 ****************************************************************************/

#ifndef __VELAGUARD_VG_DETECTOR_H
#define __VELAGUARD_VG_DETECTOR_H

#include "velaguard/vg_capture.h"
#include "velaguard/vg_types.h"

#ifdef __cplusplus
extern "C"
{
#endif

typedef struct
{
  uint32_t         windows;         /* 已处理窗口数 */
  uint32_t         sound_hits;      /* 环境声景命中数 */
  uint32_t         voice_hits;      /* 人声异常命中数 */
  uint32_t         template_hits;   /* 个性化模板命中数 */
  float            last_energy_db;
  vg_sound_class_t last_sound;
  float            last_sound_conf;
  vg_voice_kind_t  last_voice;
  float            last_voice_conf;
  uint32_t         avg_us;          /* 单窗口平均处理耗时 */
  uint32_t         max_us;          /* 单窗口最大处理耗时 */
} vg_detector_stats_t;

int  vg_detector_init(void);
void vg_detector_deinit(void);

/* 处理一个完整的 1 秒窗口（16000 样本），产生观测并投喂状态机 */

int vg_detector_process_window(const int16_t *pcm, size_t nsamples);

/* 从当前音频源拉取一个 hop（0.5 秒）并在窗口就绪时处理。
 * 返回处理的窗口数：0 表示暂无数据（暂停 / 无音频源 / wav 结束）。
 */

int vg_detector_pump(void);

/* 离线跑完整个 wav：模拟器线用真实识别链路验证五类声景 */

int vg_detector_run_file(const char *path);

void vg_detector_stats(vg_detector_stats_t *out);
void vg_detector_stats_reset(void);

/* 静音门限以下的窗口直接跳过（省电且避免噪声误报） */

void vg_detector_set_silence_db(float db);

#ifdef __cplusplus
}
