uint64_t vg_now_ms(void);

/* 虚拟时钟：离线 wav 回放与单元测试需要按窗口节奏推进时间，
 * 而不是等待真实时间流逝。启用后 vg_now_ms() 返回虚拟时间。
 */

void     vg_time_use_virtual(bool on);
bool     vg_time_is_virtual(void);
