/****************************************************************************
 * 安聆 VelaGuard - 本地提醒指示 (PRD-04)
 *
 * 按原理图修正：板上无独立蜂鸣器，声音走扬声器 media 播放接口；
 * 灯光走板载 WS2812 RGB LED（守护绿 / 警告黄 / 紧急红）。
 *
 * 硬件不可用时（模拟器线）自动降级为控制台指示，本地闭环仍完整可演示。
 ****************************************************************************/

#ifndef __VELAGUARD_VG_INDICATOR_H
#define __VELAGUARD_VG_INDICATOR_H

#include "velaguard/vg_types.h"

#ifdef __cplusplus
extern "C"
{
#endif

typedef enum
{
  VG_LED_OFF = 0,
  VG_LED_GUARD,        /* 守护中：绿色呼吸 */
  VG_LED_PAUSED,       /* 守护暂停：蓝色常亮 */
  VG_LED_NOTICE,       /* 提醒：绿色快闪一次 */
  VG_LED_WARNING,      /* 警告：黄色闪烁 */
  VG_LED_EMERGENCY     /* 紧急：红色急闪 */
} vg_led_mode_t;

int  vg_indicator_init(void);
void vg_indicator_deinit(void);

/* 设置 LED 表现（内部按 tick 产生呼吸/闪烁节奏） */

void vg_indicator_set_led(vg_led_mode_t mode);
vg_led_mode_t vg_indicator_led(void);

/* 播放分级提示音：
 *   notice    短音一次
 *   warning   间隔音 + 倒计时
 *   emergency 急促连续音
 * 播放期间按 PRD-04 时分方案让路给采集（单次 <= 2 秒）。
 */

void vg_indicator_play(vg_level_t level);

/* LCD 背光唤醒 */

void vg_indicator_backlight_wake(void);

/* 周期驱动（建议 100ms） */

void vg_indicator_tick(void);

/* 当前 LED 颜色描述，用于控制台与 UI 显示 */

const char *vg_indicator_led_text(void);

/* 是否检测到真实 LED / 扬声器硬件 */

bool vg_indicator_has_led(void);
bool vg_indicator_has_audio_out(void);

/* 录放并发能力标定结果（实机基线第一周验证，PRD-01/04） */

void vg_indicator_set_full_duplex(bool supported);
bool vg_indicator_full_duplex(void);

#ifdef __cplusplus
}
#endif

#endif /* __VELAGUARD_VG_INDICATOR_H */

/****************************************************************************
 * 安聆 VelaGuard - 本地提醒指示实现 (PRD-04)
 ****************************************************************************/

#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

#include "velaguard/vg_capture.h"
#include "velaguard/vg_indicator.h"
#include "velaguard/vg_time.h"

#ifndef CONFIG_VELAGUARD_LED_DEVICE
#  define CONFIG_VELAGUARD_LED_DEVICE "/dev/userleds"
#endif

#ifndef CONFIG_VELAGUARD_TONE_DIR
#  define CONFIG_VELAGUARD_TONE_DIR "/data/velaguard/tones"
#endif

/****************************************************************************
 * Private Data
 ****************************************************************************/

static vg_led_mode_t g_mode = VG_LED_OFF;
static int           g_led_fd = -1;
static bool          g_has_audio_out;
static bool          g_full_duplex = false;   /* 实机标定前保守假设不支持 */
static uint64_t      g_last_blink_ms;
static bool          g_blink_on;
static char          g_led_text[48] = "LED 关闭";

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/* WS2812 单灯颜色：这里通过 userled 位掩码近似表达三色状态。
 * 实机接入真实 WS2812 驱动时只需替换本函数。
 */

static void vg_led_write(uint8_t r, uint8_t g, uint8_t b)
{
  if (g_led_fd >= 0)
    {
      uint8_t mask = (uint8_t)((r ? 1 : 0) | (g ? 2 : 0) | (b ? 4 : 0));

      write(g_led_fd, &mask, 1);
    }
}

static const char *vg_mode_name(vg_led_mode_t mode)
{
  switch (mode)
    {
      case VG_LED_GUARD:     return "绿色呼吸(守护中)";
      case VG_LED_PAUSED:    return "蓝色常亮(守护暂停)";
      case VG_LED_NOTICE:    return "绿色快闪(提醒)";
      case VG_LED_WARNING:   return "黄色闪烁(警告)";
      case VG_LED_EMERGENCY: return "红色急闪(紧急)";
      default:               return "LED 关闭";
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int vg_indicator_init(void)
{
  struct stat st;

  g_led_fd = open(CONFIG_VELAGUARD_LED_DEVICE, O_WRONLY);
  if (g_led_fd < 0)
    {
      printf("[velaguard] 未检测到 LED 设备(%s)，降级为控制台指示\n",
             CONFIG_VELAGUARD_LED_DEVICE);
    }

  g_has_audio_out = (stat(CONFIG_VELAGUARD_TONE_DIR, &st) == 0);
  if (!g_has_audio_out)
    {
      printf("[velaguard] 未检测到提示音资源(%s)，降级为控制台指示\n",
             CONFIG_VELAGUARD_TONE_DIR);
    }

  vg_indicator_set_led(VG_LED_GUARD);
  return 0;
}

void vg_indicator_deinit(void)
{
  if (g_led_fd >= 0)
    {
      vg_led_write(0, 0, 0);
      close(g_led_fd);
      g_led_fd = -1;
    }
}

void vg_indicator_set_led(vg_led_mode_t mode)
{
  if (g_mode == mode)
    {
      return;
    }

  g_mode = mode;
  g_last_blink_ms = 0;
  g_blink_on = false;
  strncpy(g_led_text, vg_mode_name(mode), sizeof(g_led_text) - 1);
  g_led_text[sizeof(g_led_text) - 1] = '\0';
}

vg_led_mode_t vg_indicator_led(void)
{
  return g_mode;
}

void vg_indicator_play(vg_level_t level)
{
  const char *tone;
  uint32_t duration_ms;

  switch (level)
    {
      case VG_LEVEL_WARNING:
        tone = "warning.wav";
        duration_ms = 1200;
        break;

      case VG_LEVEL_EMERGENCY:
        tone = "emergency.wav";
        duration_ms = 1800;
        break;

      default:
        tone = "notice.wav";
        duration_ms = 400;
        break;
    }

  /* PRD-01/04：录放并发未验证通过时采用时分方案，
   * 播放期间暂停采集，单次中断上限 2 秒。
   */

  if (!g_full_duplex)
    {
      vg_capture_hold_for_playback(duration_ms);
    }

  if (g_has_audio_out)
    {
      char path[128];

      snprintf(path, sizeof(path), "%s/%s", CONFIG_VELAGUARD_TONE_DIR, tone);

      /* 交给官方 media 播放接口；这里保持与平台解耦，
       * 实机接入时替换为 media_uv_player / nxplayer 调用。
       */

      printf("[velaguard] 播放提示音 %s（%s）\n",
             path, g_full_duplex ? "录放并发" : "时分让路");
    }
  else
    {
      printf("[velaguard] 提示音(%s级) —— 无扬声器资源，控制台提示\n",
             vg_level_cn(level));
    }
}

void vg_indicator_backlight_wake(void)
{
  /* 实机接 LCD 背光 PWM；模拟器线仅记录 */

  printf("[velaguard] LCD 背光唤醒\n");
}

void vg_indicator_tick(void)
{
  uint64_t now = vg_now_ms();
  uint32_t period;

  switch (g_mode)
    {
      case VG_LED_EMERGENCY:
        period = 150;
        break;

      case VG_LED_WARNING:
        period = 400;
        break;

      case VG_LED_NOTICE:
        period = 800;
        break;

      case VG_LED_GUARD:
        period = 2000;
        break;

      default:
        period = 0;
        break;
    }

  if (period == 0)
    {
      vg_led_write(0, 0, 0);
      return;
    }

  if (now - g_last_blink_ms < period)
    {
      return;
    }

  g_last_blink_ms = now;
  g_blink_on = !g_blink_on;

  switch (g_mode)
    {
      case VG_LED_EMERGENCY:
        vg_led_write(g_blink_on ? 255 : 0, 0, 0);
        break;

      case VG_LED_WARNING:
        vg_led_write(g_blink_on ? 255 : 0, g_blink_on ? 200 : 0, 0);
        break;

      case VG_LED_PAUSED:
        vg_led_write(0, 0, 255);
        break;

      default:
        vg_led_write(0, g_blink_on ? 255 : 40, 0);
        break;
    }
}

const char *vg_indicator_led_text(void)
{
  return g_led_text;
}

bool vg_indicator_has_led(void)
{
  return g_led_fd >= 0;
}

bool vg_indicator_has_audio_out(void)
{
  return g_has_audio_out;
}

void vg_indicator_set_full_duplex(bool supported)
{
  g_full_duplex = supported;
  printf("[velaguard] 录放并发能力标定: %s\n",
         supported ? "支持全双工" : "不支持，采用时分方案(<=2s)");
}

bool vg_indicator_full_duplex(void)
{
  return g_full_duplex;
}

/****************************************************************************
 * 安聆 VelaGuard - 本地 UI (PRD-04)
 *
 * 只做三个页面：监测首页 / 事件确认页 / 历史记录页；
 * 个性化录入作为首页内的向导状态，不新增页面。
 *
 * 两个后端共享同一份页面模型：
 *   - 控制台文本后端（始终可用，模拟器线与串口演示）
 *   - LVGL 后端（CONFIG_VELAGUARD_UI_LVGL，板载 LCD）
 ****************************************************************************/

#ifndef __VELAGUARD_VG_UI_H
#define __VELAGUARD_VG_UI_H

#include "velaguard/vg_types.h"

#ifdef __cplusplus
extern "C"
{
#endif

typedef enum
{
  VG_PAGE_HOME = 0,     /* 监测首页 */
  VG_PAGE_EVENT,        /* 事件确认页 */
  VG_PAGE_HISTORY,      /* 历史记录页 */
  VG_PAGE_MAX
} vg_page_t;

/* 首页内的录入向导状态（PRD-02 入口） */

typedef enum
{
  VG_WIZ_IDLE = 0,
  VG_WIZ_PICK_KIND,
  VG_WIZ_PICK_PHRASE,
  VG_WIZ_PICK_PERSON,
  VG_WIZ_PICK_STYLE,
  VG_WIZ_RECORDING,
  VG_WIZ_DONE
} vg_wizard_state_t;

int  vg_ui_init(void);
void vg_ui_deinit(void);

void       vg_ui_set_page(vg_page_t page);
vg_page_t  vg_ui_page(void);
void       vg_ui_next_page(void);

/* 周期刷新（含 LVGL 后端重绘） */

void vg_ui_tick(void);

/* 事件变化通知：自动切到事件确认页并唤醒背光 */

void vg_ui_on_event(const vg_safety_event_t *evt, vg_state_t state);

/* 渲染当前页面为多行文本。ascii 为 true 时输出纯 ASCII，
 * 供未内置 CJK 字体的 LVGL 默认字体使用。
 */

int vg_ui_render(char *buf, size_t len, bool ascii);

/* 录入向导（板端无键盘，全部用按键在预设项之间切换） */

void              vg_ui_wizard_start(void);
void              vg_ui_wizard_next(void);
void              vg_ui_wizard_prev(void);
void              vg_ui_wizard_confirm(void);
void              vg_ui_wizard_cancel(void);
vg_wizard_state_t vg_ui_wizard_state(void);
bool              vg_ui_wizard_active(void);

/* 历史记录页翻页 */

void vg_ui_history_scroll(int delta);

#ifdef __cplusplus
}
#endif

#endif /* __VELAGUARD_VG_UI_H */

/****************************************************************************
 * 安聆 VelaGuard - 本地 UI 实现 (PRD-04)
 ****************************************************************************/

#include <inttypes.h>
#include <stdio.h>
#include <string.h>

#include "velaguard/vg_capture.h"
#include "velaguard/vg_config.h"
#include "velaguard/vg_detector.h"
#include "velaguard/vg_enroll.h"
#include "velaguard/vg_event_log.h"
#include "velaguard/vg_event_sm.h"
#include "velaguard/vg_indicator.h"
#include "velaguard/vg_time.h"
#include "velaguard/vg_ui.h"
#include "velaguard/vg_uploader.h"

/****************************************************************************
 * Private Data
 ****************************************************************************/

static vg_page_t         g_page = VG_PAGE_HOME;
static int               g_history_top;
static vg_wizard_state_t g_wizard = VG_WIZ_IDLE;
static int               g_wiz_kind;
static int               g_wiz_phrase;
static int               g_wiz_person;
static int               g_wiz_style;

/* ASCII 备用名（LVGL 默认字体不含 CJK） */

static const char * const g_type_ascii[VG_EVT_TYPE_MAX] =
{
  "ALARM BEEP", "DISTRESS VOICE", "WATER FLOW", "NAME/HELP CALL", "IMPACT"
};

static const char * const g_level_ascii[] =
{
  "NOTICE", "WARNING", "EMERGENCY"
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static const char *vg_type_txt(vg_event_type_t t, bool ascii)
{
  if (t < 0 || t >= VG_EVT_TYPE_MAX)
    {
      return ascii ? "UNKNOWN" : "未知事件";
    }

  return ascii ? g_type_ascii[t] : vg_event_type_cn(t);
}

static const char *vg_level_txt(vg_level_t l, bool ascii)
{
  if (l < VG_LEVEL_NOTICE || l > VG_LEVEL_EMERGENCY)
    {
      return ascii ? "-" : "无";
    }

  return ascii ? g_level_ascii[l] : vg_level_cn(l);
}

static const char *vg_status_txt(vg_local_status_t s, bool ascii)
{
  return ascii ? vg_status_str(s) : vg_status_cn(s);
}

#define VG_APPEND(...)                                        \
  do                                                          \
    {                                                         \
      int _n = snprintf(buf + pos, len - pos, __VA_ARGS__);   \
      if (_n < 0 || (size_t)_n >= len - pos)                  \
        {                                                     \
          return (int)pos;                                    \
        }                                                     \
      pos += (size_t)_n;                                      \
    }                                                         \
  while (0)

static int vg_render_home(char *buf, size_t len, bool ascii)
{
  vg_detector_stats_t st;
  vg_safety_event_t last;
  size_t pos = 0;
  char why[64];

  vg_detector_stats(&st);

  VG_APPEND("%s\n", ascii ? "== VelaGuard / HOME ==" : "== 安聆 VelaGuard · 监测首页 ==");

  VG_APPEND("%s: %s | %s: %s\n",
            ascii ? "Guard" : "守护",
            vg_capture_paused() ?
              (ascii ? "PAUSED" : vg_capture_pause_reason()) :
              (ascii ? "ON" : "守护中"),
            ascii ? "Src" : "音源",
            ascii ? (vg_capture_source() == VG_SRC_MIC ? "MIC" :
                     vg_capture_source() == VG_SRC_WAV ? "WAV" : "SIM")
                  : vg_capture_source_name());

  VG_APPEND("%s: %s | %s: %s\n",
            ascii ? "Net" : "上传",
            vg_uploader_online() ? (ascii ? "ONLINE" : "在线")
                                 : (ascii ? "OFFLINE" : "离线"),
            ascii ? "Clock" : "时间",
            vg_time_reliable() ? (ascii ? "SYNCED" : "已同步")
                               : (ascii ? "NOT SYNCED" : "未同步"));

  if (!ascii)
    {
      VG_APPEND("夜间判定: %s\n", vg_night_reason());
    }

  VG_APPEND("%s: %d | %s: %d\n",
            ascii ? "Pending upload" : "待发送通知", vg_uploader_pending(),
            ascii ? "Active events" : "活跃事件", vg_sm_active_count());

  VG_APPEND("%s: %s\n",
            ascii ? "LED" : "指示灯",
            ascii ? (vg_indicator_led() == VG_LED_EMERGENCY ? "RED" :
                     vg_indicator_led() == VG_LED_WARNING ? "YELLOW" :
                     vg_indicator_led() == VG_LED_PAUSED ? "BLUE" : "GREEN")
                  : vg_indicator_led_text());

  VG_APPEND("%s: %" PRIu32 " | %s: %" PRIu32 "us\n",
            ascii ? "Windows" : "已处理窗口", st.windows,
            ascii ? "Avg" : "平均耗时", st.avg_us);

  if (vg_event_log_get(0, &last) == 0)
    {
      VG_APPEND("%s: [%s] %s %s\n",
                ascii ? "Last event" : "最近事件",
                vg_level_txt(last.level, ascii),
                vg_type_txt(last.type, ascii),
                vg_status_txt(last.local_status, ascii));
    }
  else
    {
      VG_APPEND("%s\n", ascii ? "Last event: none" : "最近事件: 暂无");
    }

  if (g_wizard != VG_WIZ_IDLE)
    {
      vg_tpl_kind_t kind = (vg_tpl_kind_t)g_wiz_kind;

      VG_APPEND("---- %s ----\n",
                ascii ? "ENROLL WIZARD" : "家庭称呼与求救词录入");

      switch (g_wizard)
        {
          case VG_WIZ_PICK_KIND:
            VG_APPEND("%s: %s\n",
                      ascii ? "1/4 Kind" : "1/4 选择类别",
                      g_wiz_kind == VG_TPL_NAME ?
                        (ascii ? "NAME" : "姓名/称呼") :
                      g_wiz_kind == VG_TPL_HELP ?
                        (ascii ? "HELP" : "求救短语") :
                        (ascii ? "DIALECT" : "方言短语"));
            break;

          case VG_WIZ_PICK_PHRASE:
            VG_APPEND("%s: %s\n",
                      ascii ? "2/4 Phrase" : "2/4 选择短语",
                      vg_enroll_preset_phrase(kind, g_wiz_phrase));
            break;

          case VG_WIZ_PICK_PERSON:
            VG_APPEND("%s: %s\n",
                      ascii ? "3/4 Person" : "3/4 选择成员",
                      vg_enroll_preset_person(g_wiz_person));
            break;

          case VG_WIZ_PICK_STYLE:
            VG_APPEND("%s: %s\n",
                      ascii ? "4/4 Style" : "4/4 表达方式",
                      g_wiz_style == VG_TPL_URGENT ?
                        (ascii ? "URGENT" : "急促") :
                        (ascii ? "CALM" : "平静"));
            break;

          case VG_WIZ_RECORDING:
            VG_APPEND("%s %d/%d\n",
                      ascii ? "Recording take" : "采集次数",
                      vg_enroll_takes(), VG_ENROLL_MIN_TAKES);
            VG_APPEND("%s\n",
                      ascii ? "Guard paused, only template stored"
                            : "守护已暂停；只保存声学模板，不保存录音");
            break;

          case VG_WIZ_DONE:
            VG_APPEND("%s\n", ascii ? "Saved" : "已保存模板");
            break;

          default:
            break;
        }
    }
  else
    {
      VG_APPEND("%s: %d %s\n",
                ascii ? "Templates" : "已录入模板", vg_enroll_count(),
                ascii ? "" : "条");

      if (!vg_enroll_min_set_ready(why, sizeof(why)) && !ascii)
        {
          VG_APPEND("最小集自检: %s\n", why);
        }

      VG_APPEND("[%s] %s\n",
                ascii ? "KEY1" : "按键1",
                ascii ? "Enter enroll wizard" : "进入录入向导");
    }

  return (int)pos;
}

static int vg_render_event(char *buf, size_t len, bool ascii)
{
  vg_track_view_t view;
  size_t pos = 0;
  int n;
  int i;

  VG_APPEND("%s\n", ascii ? "== VelaGuard / EVENT ==" : "== 安聆 VelaGuard · 事件确认 ==");

  if (vg_sm_top(&view) < 0)
    {
      VG_APPEND("%s\n", ascii ? "No active event. Guarding."
                              : "当前无待确认事件，守护中。");
      return (int)pos;
    }

  VG_APPEND("[%s] %s\n",
            vg_level_txt(view.evt.level, ascii),
            vg_type_txt(view.evt.type, ascii));
  VG_APPEND("ID %s  %s %.0f%%\n", view.evt.event_id,
            ascii ? "conf" : "置信度", (double)view.evt.confidence * 100.0);
  VG_APPEND("%s %" PRIu32 "s  %s %s\n",
            ascii ? "duration" : "持续",
            view.evt.duration_sec,
            ascii ? "status" : "状态",
            vg_status_txt(view.evt.local_status, ascii));

  if (view.evt.matched_phrase[0] != '\0' && !ascii)
    {
      VG_APPEND("匹配短语: %s (%s) 重复 %u 次\n",
                view.evt.matched_phrase, view.evt.person_label,
                (unsigned)view.evt.repeat_count);
    }

  if (view.countdown_sec > 0)
    {
      VG_APPEND("%s %" PRIu32 "s\n",
                ascii ? "Countdown" : "倒计时", view.countdown_sec);
    }

  if (view.snooze_left_sec > 0)
    {
      VG_APPEND("%s %" PRIu32 "s (%s %" PRIu32 "/%" PRIu32 ")\n",
                ascii ? "Snoozed" : "稍后提醒剩余", view.snooze_left_sec,
                ascii ? "used" : "已用", view.snooze_count,
                vg_config()->snooze_max_count);
    }

  if (view.local_only)
    {
      VG_APPEND("%s\n", ascii ? "Local confirm only, no remote push"
                              : "平静单次呼喊：仅本地确认，不远程通知");
    }

  if (!ascii)
    {
      VG_APPEND("摘要: %s\n", view.evt.summary);
    }

  VG_APPEND("[%s] %s  [%s] %s  [%s] %s\n",
            ascii ? "K2" : "按键2", ascii ? "Handled" : "已处理",
            ascii ? "K3" : "按键3", ascii ? "False alarm" : "误报",
            ascii ? "K4" : "按键4", ascii ? "Snooze" : "稍后提醒");

  n = vg_sm_active_count();
  if (n > 1)
    {
      VG_APPEND("%s %d\n", ascii ? "Queued events:" : "排队事件:", n - 1);

      for (i = 1; i < n; i++)
        {
          vg_track_view_t q;

          if (vg_sm_get(i, &q) < 0)
            {
              break;
            }

          VG_APPEND("  - [%s] %s %s\n",
                    vg_level_txt(q.evt.level, ascii),
                    vg_type_txt(q.evt.type, ascii),
                    vg_status_txt(q.evt.local_status, ascii));
        }
    }

  return (int)pos;
}

static int vg_render_history(char *buf, size_t len, bool ascii)
{
  size_t pos = 0;
  int total = vg_event_log_count();
  int i;

  VG_APPEND("%s (%d/%d)\n",
            ascii ? "== VelaGuard / HISTORY ==" : "== 安聆 VelaGuard · 历史记录 ==",
            total > 0 ? g_history_top + 1 : 0, total);

  if (total == 0)
    {
      VG_APPEND("%s\n", ascii ? "No records." : "暂无记录。");
      return (int)pos;
    }

  for (i = g_history_top; i < g_history_top + 6 && i < total; i++)
    {
      vg_safety_event_t evt;
      char ts[VG_TIMESTR_LEN];

      if (vg_event_log_get(i, &evt) < 0)
        {
          break;
        }

      vg_format_time(evt.started_at, ts, sizeof(ts));
      VG_APPEND("%s [%s] %s %s%s\n",
                ts + 5,           /* 省略年份，省屏幕宽度 */
                vg_level_txt(evt.level, ascii),
                vg_type_txt(evt.type, ascii),
                vg_status_txt(evt.local_status, ascii),
                evt.time_reliable ? "" : (ascii ? " (?)" : " (时间未同步)"));
    }

  return (int)pos;
}

#undef VG_APPEND

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int vg_ui_init(void)
{
  g_page = VG_PAGE_HOME;
  g_history_top = 0;
  g_wizard = VG_WIZ_IDLE;
  return 0;
}

void vg_ui_deinit(void)
{
  g_wizard = VG_WIZ_IDLE;
}

void vg_ui_set_page(vg_page_t page)
{
  if (page >= 0 && page < VG_PAGE_MAX)
    {
      g_page = page;
      if (page == VG_PAGE_HISTORY)
        {
          g_history_top = 0;
        }
    }
}

vg_page_t vg_ui_page(void)
{
  return g_page;
}

void vg_ui_next_page(void)
{
  g_page = (vg_page_t)((g_page + 1) % VG_PAGE_MAX);
  if (g_page == VG_PAGE_HISTORY)
    {
      g_history_top = 0;
    }
}

void vg_ui_tick(void)
{
  /* 文本后端无需重绘；LVGL 后端在 vg_ui_lvgl.c 中挂接 */
}

void vg_ui_on_event(const vg_safety_event_t *evt, vg_state_t state)
{
  if (evt == NULL)
    {
      return;
    }

  if (state == VG_STATE_WARNING || state == VG_STATE_EMERGENCY)
    {
      vg_ui_set_page(VG_PAGE_EVENT);
      vg_indicator_backlight_wake();
    }
}

int vg_ui_render(char *buf, size_t len, bool ascii)
{
  if (buf == NULL || len < 64)
    {
      return -1;
    }

  buf[0] = '\0';

  switch (g_page)
    {
      case VG_PAGE_EVENT:
        return vg_render_event(buf, len, ascii);

      case VG_PAGE_HISTORY:
        return vg_render_history(buf, len, ascii);

      default:
        return vg_render_home(buf, len, ascii);
    }
}

void vg_ui_history_scroll(int delta)
{
  int total = vg_event_log_count();

  g_history_top += delta;
  if (g_history_top < 0)
    {
      g_history_top = 0;
    }

  if (g_history_top >= total)
    {
      g_history_top = total > 0 ? total - 1 : 0;
    }
}

/****************************************************************************
 * 录入向导 (PRD-02)
 ****************************************************************************/

void vg_ui_wizard_start(void)
{
  g_page = VG_PAGE_HOME;
  g_wizard = VG_WIZ_PICK_KIND;
  g_wiz_kind = VG_TPL_NAME;
  g_wiz_phrase = 0;
  g_wiz_person = 0;
  g_wiz_style = VG_TPL_CALM;

  /* 录入与守护采集互斥（PRD-01） */

  vg_capture_pause("守护已暂停：录入中");
  vg_indicator_set_led(VG_LED_PAUSED);
}

static int vg_wiz_option_count(void)
{
  switch (g_wizard)
    {
      case VG_WIZ_PICK_KIND:
        return VG_TPL_KIND_MAX;

      case VG_WIZ_PICK_PHRASE:
        return vg_enroll_preset_phrase_count((vg_tpl_kind_t)g_wiz_kind);

      case VG_WIZ_PICK_PERSON:
        return vg_enroll_preset_person_count();

      case VG_WIZ_PICK_STYLE:
        return 2;

      default:
        return 0;
    }
}

static int *vg_wiz_option_ref(void)
{
  switch (g_wizard)
    {
      case VG_WIZ_PICK_KIND:
        return &g_wiz_kind;

      case VG_WIZ_PICK_PHRASE:
        return &g_wiz_phrase;

      case VG_WIZ_PICK_PERSON:
        return &g_wiz_person;

      case VG_WIZ_PICK_STYLE:
        return &g_wiz_style;

      default:
        return NULL;
    }
}

void vg_ui_wizard_next(void)
{
  int n = vg_wiz_option_count();
  int *ref = vg_wiz_option_ref();

  if (ref != NULL && n > 0)
    {
      *ref = (*ref + 1) % n;

      if (g_wizard == VG_WIZ_PICK_KIND)
        {
          g_wiz_phrase = 0;
        }
    }
}

void vg_ui_wizard_prev(void)
{
  int n = vg_wiz_option_count();
  int *ref = vg_wiz_option_ref();

  if (ref != NULL && n > 0)
    {
      *ref = (*ref + n - 1) % n;

      if (g_wizard == VG_WIZ_PICK_KIND)
        {
          g_wiz_phrase = 0;
        }
    }
}

void vg_ui_wizard_confirm(void)
{
  switch (g_wizard)
    {
      case VG_WIZ_PICK_KIND:
        g_wizard = VG_WIZ_PICK_PHRASE;
        break;

      case VG_WIZ_PICK_PHRASE:
        g_wizard = VG_WIZ_PICK_PERSON;
        break;

      case VG_WIZ_PICK_PERSON:
        g_wizard = VG_WIZ_PICK_STYLE;
        break;

      case VG_WIZ_PICK_STYLE:
        vg_enroll_begin((vg_tpl_kind_t)g_wiz_kind,
                        (vg_tpl_style_t)g_wiz_style,
                        vg_enroll_preset_phrase((vg_tpl_kind_t)g_wiz_kind,
                                                g_wiz_phrase),
                        vg_enroll_preset_person(g_wiz_person));
        g_wizard = VG_WIZ_RECORDING;
        break;

      case VG_WIZ_RECORDING:
        if (vg_enroll_takes() >= VG_ENROLL_MIN_TAKES &&
            vg_enroll_commit() >= 0)
          {
            g_wizard = VG_WIZ_DONE;
          }
        break;

      case VG_WIZ_DONE:
      default:
        vg_ui_wizard_cancel();
        break;
    }
}

void vg_ui_wizard_cancel(void)
{
  vg_enroll_cancel();
  g_wizard = VG_WIZ_IDLE;
  vg_capture_resume();
  vg_indicator_set_led(VG_LED_GUARD);
}

vg_wizard_state_t vg_ui_wizard_state(void)
{
  return g_wizard;
}

bool vg_ui_wizard_active(void)
{
  return g_wizard != VG_WIZ_IDLE;
}

/****************************************************************************
 * 安聆 VelaGuard - 本地输入 (PRD-04)
 *
 * 主输入：板载 LRADC 按键（原理图 SW2—SW6，约 5 键）
 * 增强输入：电容触摸（若驱动可用，非依赖项）
 * 开发/演示：串口命令（与脚本注入共用入口）
 *
 * 三种输入统一映射到 vg_action_t，走完全相同的处理路径。
 ****************************************************************************/

#ifndef __VELAGUARD_VG_INPUT_H
#define __VELAGUARD_VG_INPUT_H

#include <stdbool.h>

#ifdef __cplusplus
extern "C"
{
#endif

typedef enum
{
  VG_ACT_NONE = 0,
  VG_ACT_PAGE,             /* SW2 翻页 / 录入向导中为"下一项" */
  VG_ACT_HANDLED,          /* SW3 已处理 */
  VG_ACT_FALSE_ALARM,      /* SW4 误报 */
  VG_ACT_SNOOZE,           /* SW5 稍后提醒 */
  VG_ACT_ENTER,            /* SW6 确认 / 进入录入向导 */
  VG_ACT_BACK,             /* 长按 SW6 取消 */
  VG_ACT_SCROLL_UP,
  VG_ACT_SCROLL_DOWN
} vg_action_t;

int  vg_input_init(void);
void vg_input_deinit(void);

/* 轮询硬件按键，返回本次读到的动作（无按键返回 VG_ACT_NONE） */

vg_action_t vg_input_poll(void);

/* 执行一个动作（按键与串口命令共用） */

void vg_input_dispatch(vg_action_t action);

/* 字符串 -> 动作，供串口命令使用 */

vg_action_t vg_input_parse(const char *s);

bool vg_input_has_buttons(void);

#ifdef __cplusplus
}
#endif

#endif /* __VELAGUARD_VG_INPUT_H */

/****************************************************************************
 * 安聆 VelaGuard - 本地输入实现 (PRD-04)
 ****************************************************************************/

#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

#include "velaguard/vg_event_sm.h"
#include "velaguard/vg_input.h"
#include "velaguard/vg_ui.h"

#ifndef CONFIG_VELAGUARD_BUTTON_DEVICE
#  define CONFIG_VELAGUARD_BUTTON_DEVICE "/dev/buttons"
#endif

/****************************************************************************
 * Private Data
 ****************************************************************************/

static int      g_btn_fd = -1;
static uint32_t g_last_mask;

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int vg_input_init(void)
{
  g_btn_fd = open(CONFIG_VELAGUARD_BUTTON_DEVICE, O_RDONLY | O_NONBLOCK);
  if (g_btn_fd < 0)
    {
      printf("[velaguard] 未检测到按键设备(%s)，"
             "请用串口命令 velaguard key <动作> 操作\n",
             CONFIG_VELAGUARD_BUTTON_DEVICE);
    }

  g_last_mask = 0;
  return 0;
}

void vg_input_deinit(void)
{
  if (g_btn_fd >= 0)
    {
      close(g_btn_fd);
      g_btn_fd = -1;
    }
}

bool vg_input_has_buttons(void)
{
  return g_btn_fd >= 0;
}

vg_action_t vg_input_poll(void)
{
  uint8_t raw = 0;
  uint32_t mask;
  uint32_t pressed;

  if (g_btn_fd < 0)
    {
      return VG_ACT_NONE;
    }

  if (read(g_btn_fd, &raw, sizeof(raw)) != (ssize_t)sizeof(raw))
    {
      return VG_ACT_NONE;
    }

  mask = raw;
  pressed = mask & ~g_last_mask;   /* 只取上升沿，天然去抖 */
  g_last_mask = mask;

  if (pressed & 0x01)
    {
      return VG_ACT_PAGE;
    }

  if (pressed & 0x02)
    {
      return VG_ACT_HANDLED;
    }

  if (pressed & 0x04)
    {
      return VG_ACT_FALSE_ALARM;
    }

  if (pressed & 0x08)
    {
      return VG_ACT_SNOOZE;
    }

  if (pressed & 0x10)
    {
      return VG_ACT_ENTER;
    }

  return VG_ACT_NONE;
}

vg_action_t vg_input_parse(const char *s)
{
  if (s == NULL)
    {
      return VG_ACT_NONE;
    }

  if (strcmp(s, "page") == 0)        return VG_ACT_PAGE;
  if (strcmp(s, "handled") == 0)     return VG_ACT_HANDLED;
  if (strcmp(s, "false") == 0 ||
      strcmp(s, "false_alarm") == 0) return VG_ACT_FALSE_ALARM;
  if (strcmp(s, "snooze") == 0)      return VG_ACT_SNOOZE;
  if (strcmp(s, "enter") == 0)       return VG_ACT_ENTER;
  if (strcmp(s, "back") == 0)        return VG_ACT_BACK;
  if (strcmp(s, "up") == 0)          return VG_ACT_SCROLL_UP;
  if (strcmp(s, "down") == 0)        return VG_ACT_SCROLL_DOWN;

  return VG_ACT_NONE;
}

void vg_input_dispatch(vg_action_t action)
{
  switch (action)
    {
      case VG_ACT_PAGE:
        if (vg_ui_wizard_active())
          {
            vg_ui_wizard_next();
          }
        else
          {
            vg_ui_next_page();
          }
        break;

      case VG_ACT_HANDLED:
        if (vg_ui_wizard_active())
          {
            vg_ui_wizard_prev();
          }
        else
          {
            vg_sm_ack(NULL, VG_STATUS_HANDLED);
          }
        break;

      case VG_ACT_FALSE_ALARM:
        if (!vg_ui_wizard_active())
          {
            vg_sm_ack(NULL, VG_STATUS_FALSE_ALARM);
          }
        break;

      case VG_ACT_SNOOZE:
        if (!vg_ui_wizard_active())
          {
            if (vg_sm_ack(NULL, VG_STATUS_SNOOZED) == -2)
              {
                printf("[velaguard] 稍后提醒次数已用尽，"
                       "本次超时将按无人响应升级\n");
              }
          }
        break;

      case VG_ACT_ENTER:
        if (vg_ui_wizard_active())
          {
            vg_ui_wizard_confirm();
          }
        else if (vg_ui_page() == VG_PAGE_HOME)
          {
            vg_ui_wizard_start();
          }
        break;

      case VG_ACT_BACK:
        if (vg_ui_wizard_active())
          {
            vg_ui_wizard_cancel();
          }
        else
          {
            vg_ui_set_page(VG_PAGE_HOME);
          }
        break;

      case VG_ACT_SCROLL_UP:
        vg_ui_history_scroll(-1);
        break;

      case VG_ACT_SCROLL_DOWN:
        vg_ui_history_scroll(1);
        break;

      default:
        break;
    }
}

