/* 安全字符串拷贝：总是以 '\0' 结尾，超长截断 */

void vg_strlcpy(char *dst, const char *src, size_t size);

/* 枚举 <-> 协议字符串 */

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void vg_strlcpy(char *dst, const char *src, size_t size)
{
  size_t n;

  if (dst == NULL || size == 0)
    {
      return;
    }

  if (src == NULL)
    {
      dst[0] = '\0';
      return;
    }

  n = strlen(src);
  if (n >= size)
    {
      n = size - 1;
    }

  memcpy(dst, src, n);
  dst[n] = '\0';
}

