python3 - <<'PY'
import re, pathlib

files = [p for p in pathlib.Path('.').rglob('*.c')]

def find_call(text, start):
    """start 指向 'strncpy(' 的 '(' 位置，返回匹配右括号索引"""
    depth = 0
    i = start
    while i < len(text):
        if text[i] == '(':
            depth += 1
        elif text[i] == ')':
            depth -= 1
            if depth == 0:
                return i
        i += 1
    return -1

changed = []
for p in files:
    src = p.read_text(encoding='utf-8')
    out = src
    idx = 0
    while True:
        m = re.search(r'\bstrncpy\s*\(', out[idx:])
        if not m:
            break
        open_paren = idx + m.end() - 1
        close = find_call(out, open_paren)
        if close < 0:
            break
        args = out[open_paren+1:close]
        # 拆最外层逗号
        parts, depth, cur = [], 0, ''
        for ch in args:
            if ch == '(':
                depth += 1
            elif ch == ')':
                depth -= 1
            if ch == ',' and depth == 0:
                parts.append(cur); cur = ''
            else:
                cur += ch
        parts.append(cur)
        if len(parts) == 3:
            size = parts[2].strip()
            size = re.sub(r'^\(?\s*(.+?)\s*\)?\s*-\s*1$', r'\1', size)
            new = 'vg_strlcpy(' + parts[0] + ',' + parts[1] + ', ' + size + ')'
            out = out[:idx + m.start()] + new + out[close+1:]
            idx = idx + m.start() + len(new)
        else:
            idx = close
    if out != src:
        p.write_text(out, encoding='utf-8')
        changed.append(str(p))

print('\n'.join(changed))
PY

