void vg_utf8_trim(char *s)
{
  size_t n;
  size_t i;

  if (s == NULL)
    {
      return;
    }

  n = strlen(s);
  if (n == 0)
    {
      return;
    }

  /* 从尾部回退，找到最后一个字符的起始字节并检查其长度是否完整 */

  i = n;
  while (i > 0)
    {
      unsigned char c = (unsigned char)s[i - 1];

      if ((c & 0xc0) != 0x80)
        {
          size_t need = (c < 0x80) ? 1 :
                        ((c & 0xe0) == 0xc0) ? 2 :
                        ((c & 0xf0) == 0xe0) ? 3 :
                        ((c & 0xf8) == 0xf0) ? 4 : 1;

          if (i - 1 + need > n)
            {
              s[i - 1] = '\0';
            }

          return;
        }

      i--;
    }
}

